/* Déclic — Anglais B1 (unités 10 à 12). Format : docs/ANGLAIS.md */
(()=>{
// X('a',['b','c'],'d') → ['a b d','a c d'] : toutes les variantes d’une réponse (une partie vide '' est sautée)
const X=(...parts)=>parts.reduce((acc,p)=>acc.flatMap(a=>[].concat(p).map(b=>b?(a?a+' '+b:b):a)),['']);
COURS.push(

/* ======================================================================
   10. Technology
   ====================================================================== */
{subj:'en', sem:'b1', id:'en-b1-technology', o:10, h:'Technology', p:'Décrire un objet, dire à quoi il sert et pour qui : les propositions relatives (déterminatives et non déterminatives) et les noms composés du vocabulaire technique.', steps:[
 {kind:'Écoute', h:'Choosing a tablet',
  p:`<p>By the end of this unit, you will be able to describe a device precisely, say what it does and who it is for, and write a clear product review.</p>
<p>Ruth wants to buy a tablet for her father. She asks her friend Dev, who works in IT, for advice. <b>Listen without reading</b>, twice if you need to, then answer. The script appears after your answer.</p>
<p><b>Question:</b> which tablet does Dev recommend, and why?</p>`,
  audio:[['Ruth','Dev, have you got a minute? I need some advice. My dad wants a tablet, and I’ve got no idea which one to get him.'],['Dev','Sure. What does he want to do with it?'],['Ruth','Mainly video calls with my brother, who lives in Canada. And he likes reading the news.'],['Dev','OK. How old is he?'],['Ruth','He’s eighty-two, and he’s not very good with technology. The phone that we gave him last Christmas is still in its box.'],['Dev','Right. Then you need something that’s really easy to use. Forget the expensive models with lots of features he’ll never touch.'],['Ruth','What about the one that’s on offer at the supermarket? It’s only ninety pounds.'],['Dev','I wouldn’t. The battery life is terrible, and the screen is quite small. Have a look at the Lumo 10. It’s the one my mum uses.'],['Ruth','Is it easy to set up?'],['Dev','Very. It has a big screen, which is great for reading, and a simple mode that hides all the apps he doesn’t need. The battery lasts about two days.'],['Ruth','And video calls?'],['Dev','There’s a button on the home screen that starts a call with one tap. My mum, who’s seventy-nine and hates computers, calls me every evening now.'],['Ruth','That sounds perfect. How much is it?'],['Dev','Around two hundred pounds. It’s not cheap, but it’s worth it.']], cache:true,
  opts:['The supermarket tablet, because it is cheap and the battery lasts two days.','The most expensive model, because it has the most features.','The Lumo 10, because it is simple, has a big screen and a one-tap video call button.','The Lumo 10, because it is the cheapest tablet in the shop.'], ans:2,
  why:'Dev conseille la Lumo 10 : un grand écran (<i lang="en">a big screen, which is great for reading</i>), un mode simplifié et un bouton qui lance un appel vidéo d’un seul geste. Elle coûte environ 200 livres. La tablette du supermarché coûte 90 livres, mais son autonomie est mauvaise (<i lang="en">the battery life is terrible</i>).'},

 {kind:'Vocabulaire', h:'Devices and their features',
  p:`<p>Here are useful words and expressions from the dialogue, and a few more. Tap a line to hear it, then repeat it aloud. These words go into your vocabulary review.</p>`,
  mots:[['a device','un appareil','Please switch off all your devices.'],['battery life','l’autonomie (de la batterie)','The battery life is terrible: two hours at most.'],['to run out of battery','tomber à court de batterie','My phone ran out of battery in the middle of the call.'],['to charge','recharger','I charge my phone every night.'],['a charger','un chargeur','Have you seen my phone charger?'],['a screen / a touchscreen','un écran / un écran tactile','The screen is too small for reading.'],['user-friendly / easy to use','facile à utiliser','The app is really user-friendly.'],['a feature','une fonction, une caractéristique','It has lots of features he’ll never use.'],['storage','la mémoire, l’espace de stockage','I haven’t got enough storage for all my photos.'],['on offer','en promotion','Tablets are on offer this week.'],['It’s worth it.','Ça vaut le coup.','It’s not cheap, but it’s worth it.'],['the home screen','l’écran d’accueil','The button is on the home screen.']],
  note:'<b>Attention :</b> « recharger son téléphone » se dit simplement <i lang="en">charge your phone</i> (<i lang="en">recharge</i> existe, mais il est moins courant). En anglais britannique, on dit <i lang="en">a mobile (phone)</i> ; en américain, <i lang="en">a cell phone</i>.'},

 {kind:'Vocabulaire', h:'Using technology',
  p:`<p>Now the verbs you need to talk about what you do with a device. Many of them are phrasal verbs. Tap a line to hear it and repeat it.</p>`,
  mots:[['to download / to install an app','télécharger / installer une application','I downloaded the app, but it won’t install.'],['to update','mettre à jour','You should update the software regularly.'],['to log in / to sign in','se connecter (à un compte)','I can’t log in: I’ve forgotten my password.'],['to log out / to sign out','se déconnecter','Always log out on a shared computer.'],['to back up (your files)','sauvegarder (ses fichiers)','Back up your photos before you reset the phone.'],['to crash','planter (programme, ordinateur)','My laptop crashed and I lost my work.'],['to freeze','se figer, bloquer','The screen froze, so I restarted the phone.'],['to set up','configurer, installer','It took ten minutes to set up the tablet.'],['to turn on / to switch off','allumer / éteindre','Switch off your phone during the film.'],['to plug in','brancher','Plug the charger in next to the bed.'],['a password','un mot de passe','Choose a password that is hard to guess.']],
  note:'<b>Piège :</b> <i lang="en">download</i> = télécharger <b>vers</b> ton appareil ; <i lang="en">upload</i> = envoyer <b>vers</b> internet (une photo sur un réseau social). Et « se connecter » à un compte se dit <i lang="en">log in</i>, mais à un réseau wifi, <i lang="en">connect to the wifi</i>.'},

 {kind:'Pratique', h:'Recall: a forgotten password',
  p:`<p>Write the sentence in English. Use the vocabulary of this unit.</p><p><b>Question:</b> how do you say «&nbsp;J’ai oublié mon mot de passe, alors je ne peux pas me connecter.&nbsp;»?</p>`, lab:'In English',
  txt:X(['I’ve forgotten','I forgot'],'my password,',['so','and'],['I can’t','I’m not able to'],['log in.','sign in.','log on.']),
  why:'<i lang="en">I’ve forgotten my password, so I can’t log in.</i> Le present perfect (<i lang="en">I’ve forgotten</i>) insiste sur le résultat présent : je ne m’en souviens toujours pas. <i lang="en">sign in</i> est aussi correct.'},

 {kind:'Grammaire', h:'Defining relative clauses: who, which, that, whose, where',
  p:`<p>Dans le dialogue, Ruth dit <i lang="en">The phone <b>that we gave him last Christmas</b> is still in its box</i>, et Dev conseille <i lang="en">something <b>that’s really easy to use</b></i>. Sans la partie en gras, on ne saurait pas de quel téléphone il s’agit : c’est une <b>relative déterminative</b> (<i lang="en">defining relative clause</i>). Elle identifie la personne ou la chose dont on parle.</p>
<div class="def"><p>Le pronom relatif dépend de l’antécédent :</p><ul><li><b>who</b> (ou <b>that</b>) pour une personne : <i lang="en">the woman who designed the app</i>.</li><li><b>which</b> (ou <b>that</b>) pour une chose ou un animal : <i lang="en">a tablet which (that) has a big screen</i>.</li><li><b>whose</b> pour la possession (son, sa, leur) : <i lang="en">a friend whose son works in IT</i>.</li><li><b>where</b> pour un lieu : <i lang="en">the shop where I bought it</i>.</li></ul><p>Pas de virgule avant une relative déterminative.</p></div>
<div class="idea"><p>Quand le pronom est <b>complément d’objet</b> du verbe de la relative, on le supprime très souvent, surtout à l’oral : <i lang="en">the phone (that) we gave him</i>, <i lang="en">the one (that) my mum uses</i>. Quand il est <b>sujet</b>, il est obligatoire : <i lang="en">a button <b>that</b> starts a call</i> (c’est le bouton qui lance l’appel). La préposition se place souvent à la fin : <i lang="en">the app I told you about</i> = l’appli dont je t’ai parlé.</p></div>
<div class="ex"><p><i lang="en">The app that I use most is my bank’s app.</i> → <i lang="en">The app I use most…</i> (objet : on peut supprimer)<br><i lang="en">The man who fixed my laptop was very kind.</i> (sujet : obligatoire)</p></div>
<div class="warn"><p>Pièges des francophones : <b>what</b> n’est jamais un relatif après un nom : <i lang="en">the phone <s>what</s> I bought</i> → <i lang="en">the phone (that) I bought</i>. Ne répète pas le pronom : <i lang="en">the laptop that I bought <s>it</s></i>. <b>which</b> ne s’emploie pas pour une personne. Et « dont » n’est pas toujours <b>whose</b> : « l’appli dont je t’ai parlé » = <i lang="en">the app I told you about</i>.</p></div>`,
  audio:'The phone that we gave him last Christmas is still in its box. There’s a button that starts a call. It’s the one my mum uses. The app I told you about is free.'},

 {kind:'Méthode', h:'Joining two sentences with a relative pronoun',
  p:`<p><b>Quand :</b> pour relier deux phrases courtes qui parlent du même nom, et éviter les répétitions (<i lang="en">I bought a laptop. It crashes every day.</i>). <b>Pourquoi ça marche :</b> le pronom relatif remplace le pronom qui reprenait le nom dans la 2e phrase. <b>Comment :</b></p>
<ol><li>Repère le nom commun aux deux phrases (l’antécédent) et le mot qui le reprend dans la 2e (<i lang="en">he, she, it, him, her, his, there</i>…).</li><li>Choisis le relatif : personne → <b>who/that</b> ; chose → <b>which/that</b> ; possessif (<i lang="en">his, her, its, their</i>) → <b>whose</b> ; lieu (<i lang="en">there</i>) → <b>where</b>.</li><li>Place la relative juste après l’antécédent et <b>supprime</b> le mot répété.</li><li>Si le relatif est complément d’objet, tu peux le supprimer.</li></ol>`,
  demo:{enonce:'Relie les deux phrases : <i lang="en">The laptop crashes every day. I bought it last month.</i>',
   etapes:[{f:'Antécédent : <i lang="en">the laptop</i>, repris par <i lang="en">it</i> dans la 2e phrase.',w:'C’est ce nom qui va recevoir la relative.'},
    {f:'Chose → <i lang="en">which</i> ou <i lang="en">that</i>. Ici <i lang="en">it</i> est complément de <i lang="en">bought</i> (<i lang="en">I bought it</i>).',w:'Le relatif remplace <i lang="en">it</i> : il est donc complément d’objet.'},
    {f:'<i lang="en">The laptop <b>that</b> I bought last month crashes every day.</i>',w:'La relative se place juste après <i lang="en">the laptop</i>, et <i lang="en">it</i> disparaît : jamais <i lang="en">that I bought it</i>.'},
    {f:'<i lang="en">The laptop I bought last month crashes every day.</i>',w:'Comme le relatif est objet, on peut le supprimer : c’est la version la plus naturelle à l’oral.'}],
   conclusion:'<i lang="en">The laptop (that / which) I bought last month crashes every day.</i> Avec un relatif sujet (<i lang="en">a laptop that crashes</i>), on le garde toujours.'}},

 {kind:'Pratique', h:'Practice: choose the pronoun',
  p:`<p>Complete the sentence with one relative pronoun.</p><p><b>Question:</b> <i lang="en">My neighbour is a woman ___ son repairs phones.</i></p>`, lab:'One word', txt:['whose'],
  why:'Le fils <b>de</b> la voisine (<i lang="en">her son</i>) : la possession se dit avec <i lang="en">whose</i>. <i lang="en">My neighbour is a woman whose son repairs phones.</i>'},

 {kind:'Pratique', h:'Practice: join the sentences',
  p:`<p>Join the two sentences with a relative pronoun. Do not repeat <i lang="en">there</i>.</p><p><b>Question:</b> <i lang="en">That’s the shop. I bought my headphones there.</i></p>`, lab:'Your sentence', long:true,
  txt:X(['That’s','That is'],'the shop',['where I bought my headphones.','I bought my headphones in.','that I bought my headphones in.','which I bought my headphones in.','in which I bought my headphones.']),
  why:'<i lang="en">there</i> désigne un lieu : <i lang="en">That’s the shop where I bought my headphones.</i> On peut aussi rejeter la préposition à la fin : <i lang="en">That’s the shop I bought my headphones in.</i>'},

 {kind:'Pratique', h:'Practice: no pronoun needed',
  p:`<p>Put the words in order. The relative pronoun has been left out, and the preposition goes at the end of the relative clause.</p><p><b>Question:</b> how do you say «&nbsp;L’appli dont je t’ai parlé est gratuite maintenant&nbsp;»?</p>`,
  ordre:['The app','I','told','you','about','is','now','free.'], alt:['The app I told you about is free now.','Now the app I told you about is free.'],
  why:'<i lang="en">The app I told you about is now free.</i> Le relatif (<i lang="en">that</i>) est objet, donc il disparaît, et <i lang="en">about</i> reste à la fin. Piège : « dont » ne se traduit pas ici par <i lang="en">whose</i>.'},

 {kind:'Grammaire', h:'Non-defining relative clauses: extra information',
  p:`<p>Dev dit <i lang="en">My mum, <b>who’s seventy-nine and hates computers</b>, calls me every evening now.</i> On sait déjà de qui il parle (il n’a qu’une mère) : la relative ajoute une <b>information en plus</b>, qu’on pourrait retirer sans changer l’identité de la personne. C’est une relative <b>non déterminative</b> (<i lang="en">non-defining relative clause</i>).</p>
<div class="def"><p>Elle se place entre <b>virgules</b> (ou entre une virgule et le point final) et commence par <b>who</b> (personne), <b>which</b> (chose), <b>whose</b> ou <b>where</b>. <b>Jamais that</b>, et on ne supprime <b>jamais</b> le pronom.</p></div>
<div class="idea"><p>La virgule change le sens. <i lang="en">My brother who lives in Canada calls every Sunday</i> : j’ai plusieurs frères, je parle de celui du Canada. <i lang="en">My brother, who lives in Canada, calls every Sunday</i> : j’ai un seul frère et, au passage, il vit au Canada. Ces relatives sont surtout écrites ; à l’oral, on les marque par une petite pause.</p></div>
<div class="ex"><p><i lang="en">It has a big screen, which is great for reading.</i> Ici, <b>which</b> reprend une idée entière : c’est le « ce qui » du français.<br><i lang="en">The battery died during the call, which was really annoying.</i> = …, ce qui était vraiment pénible.</p></div>
<div class="warn"><p>Pièges : <i lang="en">The Lumo 10, <s>that</s> which costs £200, is easy to use.</i> Et « ce qui / ce que » qui reprend toute une phrase se dit <b>, which</b>, jamais <b>, what</b> : <i lang="en">He forgot his password again, <s>what</s> which is typical.</i></p></div>`,
  audio:'My brother, who lives in Canada, calls every Sunday. It has a big screen, which is great for reading. The battery died during the call, which was really annoying.'},

 {kind:'Pratique', h:'Practice: add extra information',
  p:`<p>Join the two sentences with a non-defining relative clause. Put the new information (his age) in the middle of the first sentence, between commas.</p><p><b>Question:</b> <i lang="en">My grandfather has just bought a smartphone. He is eighty-five.</i></p>`, lab:'Your sentence', long:true,
  txt:X('My grandfather,',['who is eighty-five,','who’s eighty-five,','who is 85,','who’s 85,'],'has just bought a smartphone.'),
  why:'<i lang="en">My grandfather, who is eighty-five, has just bought a smartphone.</i> On n’a qu’un grand-père de ce côté : l’âge est une information en plus, donc des virgules et <i lang="en">who</i>, jamais <i lang="en">that</i>.'},

 {kind:'Pratique', h:'Practice: which for a whole idea',
  p:`<p>Translate into English. Use <i lang="en">which</i> to refer to the whole first part of the sentence.</p><p><b>Question:</b> «&nbsp;Le téléphone a une très bonne autonomie, ce qui est pratique.&nbsp;»</p>`, lab:'In English', long:true,
  txt:[...X(['The phone has','The phone has got','The phone’s got'],['very good battery life,','a very good battery life,','really good battery life,','a really good battery life,','great battery life,'],'which is',['practical.','handy.','useful.','convenient.']),
       ...X(['The phone’s battery life is','The battery life of the phone is'],['very good,','really good,','great,'],'which is',['practical.','handy.','useful.','convenient.'])],
  why:'<i lang="en">The phone has very good battery life, which is handy.</i> « ce qui » reprend toute l’idée qui précède : <i lang="en">, which</i>, avec une virgule. <i lang="en">, what is practical</i> est impossible.'},

 {kind:'Grammaire', h:'Compound nouns: a phone charger',
  p:`<p>« Le chargeur de téléphone », « l’écran d’accueil », « l’autonomie de la batterie » : en français, on relie deux noms par « de ». En anglais, on les colle simplement, <b>dans l’ordre inverse</b> : <i lang="en">a phone charger, the home screen, battery life</i>. C’est le <b>nom composé</b> (<i lang="en">compound noun</i>), partout dans le vocabulaire technique.</p>
<div class="def"><p><b>nom 1 + nom 2</b> : le <b>dernier</b> nom est le nom principal ; le premier précise de quel type il s’agit, comme un adjectif. <i lang="en">a phone charger</i> = un chargeur (pour téléphone). Ils s’écrivent en deux mots (<i lang="en">phone charger</i>), en un mot (<i lang="en">password, keyboard, laptop</i>) ou parfois avec un trait d’union : le dictionnaire tranche.</p></div>
<div class="idea"><p>Le premier nom reste <b>au singulier</b>, même si le sens est pluriel : <i lang="en">a <b>shoe</b> shop</i> (un magasin de chaussures), <i lang="en">a <b>password</b> manager</i>. Avec un nombre, l’ensemble devient un adjectif invariable avec des traits d’union : <i lang="en">a ten-<b>minute</b> video</i>, <i lang="en">a two-<b>year</b> guarantee</i>. Pour la fonction d’un objet, on trouve aussi <b>-ing + nom</b> : <i lang="en">a charging cable</i> (un câble pour charger), <i lang="en">a washing machine</i>.</p></div>
<div class="ex"><p>un écran d’ordinateur → <i lang="en">a computer screen</i><br>une mise à jour logicielle → <i lang="en">a software update</i><br>une garantie de deux ans → <i lang="en">a two-year guarantee</i></p></div>
<div class="warn"><p>Pièges : <i lang="en"><s>a charger of phone</s></i>, <i lang="en"><s>a ten-minutes video</s></i>, <i lang="en"><s>a shoes shop</s></i>. Pour ce qui appartient à une personne, on garde le <b>’s</b> : <i lang="en">my dad’s tablet</i> (la tablette de mon père), pas <i lang="en"><s>my dad tablet</s></i>.</p></div>`,
  audio:'a phone charger, the home screen, battery life, a computer screen, a ten-minute video, a two-year guarantee'},

 {kind:'Pratique', h:'Practice: build a compound noun',
  p:`<p>Write the compound noun in English, with its article.</p><p><b>Question:</b> «&nbsp;un appel vidéo de dix minutes&nbsp;»</p>`, lab:'In English',
  txt:['a ten-minute video call','a 10-minute video call','ten-minute video call','10-minute video call'],
  why:'<i lang="en">a ten-minute video call</i> : le nom principal (<i lang="en">call</i>) à la fin, <i lang="en">video</i> devant, et la durée en adjectif invariable : <i lang="en">ten-minute</i>, sans s.'},

 {kind:'Prononciation', h:'Stress in compound nouns',
  p:`<p>En français, l’accent tombe à la fin du groupe de mots. Dans un nom composé anglais, l’accent principal tombe en général sur le <b>premier</b> élément : <i lang="en"><b>PHONE</b> charger, <b>PASS</b>word, <b>HOME</b> screen, <b>BAT</b>tery life, <b>KEY</b>board, <b>LAP</b>top</i>.</p>
<div class="def"><p>Nom composé : accent sur le 1er mot. Adjectif + nom : accent sur le nom. <i lang="en">a <b>GREEN</b>house</i> (une serre) / <i lang="en">a green <b>HOUSE</b></i> (une maison verte).</p></div>
<div class="warn"><p>Les francophones accentuent souvent la dernière syllabe (« pass<b>WORD</b> », « lap<b>TOP</b> ») : l’anglophone comprend alors moins bien. Mets de l’énergie sur la première syllabe et avale un peu la suite.</p></div>
<p>Listen, then repeat the sentence below.</p>`,
  dire:'Where’s my phone charger? My laptop needs a new password.'},

 {kind:'Lecture', h:'A product review',
  p:`<p>Read this review from a shopping website. You can also listen to it.</p>
<div class="blk" data-t="Review: the Inkwell e-reader (4/5)"><p lang="en">I’m a commuter who reads on the train every day, so I wanted a device that was lighter than a book and easy on the eyes. After two months with the Inkwell, I’m impressed. The screen, which isn’t like a normal tablet screen, looks like real paper, and you can read it in bright sunlight. The battery life is amazing: I charge it about once every three weeks. The built-in light, which you can make warmer in the evening, means I can read in bed without waking my partner.</p><p lang="en">It isn’t perfect, though. The online shop where you buy the books is slow, and the search function is hard to use. I also miss the feeling of turning real pages. And if you like magazines with lots of photos, this isn’t the device for you: everything is in black and white.</p><p lang="en">Would I recommend it? Yes, to anyone who reads a lot of novels. People whose main interest is comics or cookbooks should probably choose a tablet instead.</p></div>
<p><b>Question:</b> according to the review, who should <b>not</b> buy the Inkwell?</p>`,
  audio:'I’m a commuter who reads on the train every day, so I wanted a device that was lighter than a book and easy on the eyes. After two months with the Inkwell, I’m impressed. The screen, which isn’t like a normal tablet screen, looks like real paper, and you can read it in bright sunlight. The battery life is amazing: I charge it about once every three weeks. The built-in light, which you can make warmer in the evening, means I can read in bed without waking my partner. It isn’t perfect, though. The online shop where you buy the books is slow, and the search function is hard to use. I also miss the feeling of turning real pages. And if you like magazines with lots of photos, this isn’t the device for you: everything is in black and white. Would I recommend it? Yes, to anyone who reads a lot of novels. People whose main interest is comics or cookbooks should probably choose a tablet instead.',
  opts:['People who read on the train','People who read in bed','People who mainly read comics or cookbooks','People who read a lot of novels'], ans:2,
  why:'<i lang="en">People whose main interest is comics or cookbooks should probably choose a tablet instead</i> : l’écran est en noir et blanc. Remarque les relatives du texte : <i lang="en">a commuter who reads…</i>, <i lang="en">the screen, which…</i>, <i lang="en">the online shop where…</i>, <i lang="en">people whose…</i>'},

 {kind:'Dictée', h:'Dictation: a broken charger',
  p:'Listen and write the sentence exactly. You can listen as many times as you like and use «&nbsp;Plus lentement&nbsp;».',
  dictee:'The charger that came with my phone stopped working after a week, which is ridiculous.',
  why:'Deux relatives : <i lang="en">that came with my phone</i> (déterminative, sans virgule) et <i lang="en">, which is ridiculous</i> (qui reprend toute l’idée, avec une virgule).'},

 {kind:'Oral', h:'Repeat from memory',
  p:'This time the sentence is not written. Listen, then say it from memory. Stress the first part of the compound noun: <i lang="en"><b>VI</b>deo calls</i>.',
  dire:{t:'It’s a tablet that lets you make video calls with one tap.', cache:true}},

 {kind:'Oral', h:'Describe an object you use every day',
  p:`<p>Speak for about one minute. Describe an object you use every day: what it is, what it does, who it is useful for, one thing you like and one thing you don’t like. Use at least two relative clauses and two compound nouns. Tap «&nbsp;Parler&nbsp;», then «&nbsp;J’ai fini&nbsp;».</p>`,
  oral:{modele:'The device I use most is my electric bike, which I bought two years ago. It’s a normal bike with a small motor that helps you when you’re going uphill. The battery, which you can take off, gives you about sixty kilometres, and I charge it at work. It’s perfect for people who live in a hilly town like mine. The thing I don’t like is the weight: it’s really heavy, so it’s hard to carry up the stairs. But it’s worth it: I hardly use my car any more.',
   criteres:['I said what the object is and what it does','I used at least two relative clauses (who, which, that, whose, where)','I added extra information with a short pause (…, which…,)','I used compound nouns (battery life, phone charger…) with the stress on the first word','I gave one advantage and one disadvantage']}},

 {kind:'Écriture', h:'Write a product review',
  p:'You bought a gadget recently (a phone, headphones, a smartwatch, a coffee machine…). Write a review for a shopping website, about 120 words. Say what it is and who it is for, describe two or three features, give one or two disadvantages, and say whether you recommend it. Use defining and non-defining relative clauses and some compound nouns.',
  ecrire:{min:110, modele:'I bought the Pulse 2 headphones last month, and I’m really happy with them. They’re wireless headphones that are designed for people who travel a lot. The noise cancelling, which you switch on with a button on the left side, works brilliantly on planes and trains. The battery life is excellent: about thirty hours, so I only charge them once a week. The sound quality is also very good for the price. However, there are two problems. The carrying case is quite big, so it doesn’t fit in my jacket pocket, and the app that controls the settings crashes quite often. Overall, I’d recommend them to anyone whose daily journey is long and noisy. They aren’t cheap, but they’re worth it.',
   criteres:[{t:'I used a defining relative clause (who, that, whose, where)', re:'\\b(who|that|whose|where)\\b'},{t:'I added extra information between commas (…, which… / …, who…)', re:',\\s*(which|who|whose|where)\\b'},{t:'I mentioned a disadvantage (but, however, though…)', re:'\\b(but|however|though|although|unfortunately)\\b'},{t:'I said whether I recommend it', re:'\\brecommend'},'I used at least two compound nouns (battery life, sound quality, phone case…)','I checked: no « that » after a comma, no « what » after a noun']}},

 {kind:'Récapitulatif', h:'Ce qu’il faut retenir',
  p:`<div class="keep"><ul><li>Relatives <b>déterminatives</b> (sans virgule) : elles disent de qui ou de quoi on parle. <b>who/that</b> (personne), <b>which/that</b> (chose), <b>whose</b> (possession), <b>where</b> (lieu).</li><li>Relatif <b>objet</b> : on peut le supprimer (<i lang="en">the phone we gave him</i>). Relatif <b>sujet</b> : obligatoire (<i lang="en">a button that starts a call</i>). La préposition va souvent à la fin : <i lang="en">the app I told you about</i>.</li><li>Jamais <i lang="en">what</i> après un nom, jamais de pronom répété (<i lang="en"><s>that I bought it</s></i>), jamais <i lang="en">which</i> pour une personne.</li><li>Relatives <b>non déterminatives</b> : entre virgules, information en plus, <b>jamais that</b>, pronom jamais supprimé. <b>, which</b> = « ce qui / ce que » pour reprendre toute une idée.</li><li>Noms composés : nom principal à la fin, premier nom au singulier (<i lang="en">a phone charger, a shoe shop, a ten-minute video</i>), accent sur le premier mot. Possession d’une personne : <i lang="en">my dad’s tablet</i>.</li><li>Vocabulaire : <i lang="en">battery life, run out of battery, charge, log in, back up, update, crash, set up, user-friendly, It’s worth it</i>.</li></ul></div>`},

 {kind:'Mission', h:'Calling technical support',
  p:'You work in a shop’s customer service team, and you are listening to a recording of a support call to check how it went. Listen to the conversation, then answer the questions one by one. You can listen again at any time.',
  audio:[['Agent','Good morning, Techline support. My name’s Hannah. How can I help?'],['Customer','Hi. I’ve got a problem with a laptop that I bought from you three weeks ago. It won’t turn on.'],['Agent','I’m sorry to hear that. When you plug it in, does the light on the charger come on?'],['Customer','No, it doesn’t. That’s the strange thing. The charger, which worked perfectly yesterday, seems completely dead.'],['Agent','OK, so the problem might be the charger, not the laptop. Have you tried a different socket?'],['Customer','Yes, I’ve tried three.'],['Agent','Right. Your laptop has a two-year guarantee, so we’ll send you a new charger free of charge. Can I have the email address that you used for your order?'],['Customer','Sure. It’s j dot okafor at mailbox dot com.'],['Agent','Thank you. The new charger should arrive within three working days. If the laptop still doesn’t work after that, call us back and we’ll arrange a repair.']], cache:true,
  parts:[
   {q:'a) What does the agent think the problem is?', opts:['The laptop’s screen','The customer’s email account','The socket in the customer’s house','The charger'], ans:3, hint:'Listen to what the agent says after the customer describes the light on the charger.', why:'<i lang="en">The problem might be the charger, not the laptop.</i> Le client a déjà essayé trois prises : ce n’est pas la prise.'},
   {q:'b) How long is the guarantee? Write it as a compound noun, the way the agent says it (example: <i lang="en">a three-month guarantee</i>).', lab:'Compound noun', txt:['a two-year guarantee','two-year guarantee','a 2-year guarantee','2-year guarantee'], hint:'The number becomes part of an adjective, with no s.', why:'<i lang="en">a two-year guarantee</i> : garantie de deux ans. <i lang="en">year</i> reste au singulier.'},
   {q:'c) When should the new charger arrive?', opts:['Tomorrow morning','Within three working days','In two weeks','Only after a repair'], ans:1, hint:'The agent gives a number of days at the end of the call.', why:'<i lang="en">The new charger should arrive within three working days.</i>'},
   {q:'d) The customer wants to explain his problem in one sentence. Join the two sentences, putting the relative clause after <i lang="en">The laptop</i>: <i lang="en">The laptop won’t turn on. I bought it from you three weeks ago.</i>', lab:'Your sentence', long:true, txt:X('The laptop',['','that','which'],'I bought from you three weeks ago',['won’t turn on.','doesn’t turn on.']), hint:'The relative clause goes straight after “The laptop”, and “it” disappears.', why:'<i lang="en">The laptop (that) I bought from you three weeks ago won’t turn on.</i> Le relatif est objet de <i lang="en">bought</i>, donc on peut l’omettre, mais on ne garde jamais <i lang="en">it</i>.'}],
  sol:'<p lang="en">Agent: Good morning, Techline support… – Customer: I’ve got a problem with a laptop that I bought from you three weeks ago. It won’t turn on. – … The charger, which worked perfectly yesterday, seems completely dead. – … Your laptop has a two-year guarantee, so we’ll send you a new charger free of charge… It should arrive within three working days.</p><p>Le problème vient probablement du chargeur. La garantie dure deux ans (<i lang="en">a two-year guarantee</i>), le nouveau chargeur arrive sous trois jours ouvrables. Phrase du client : <i lang="en">The laptop (that) I bought from you three weeks ago won’t turn on.</i></p>'},

 {kind:'Mission', h:'Selling your old phone',
  p:`<p>You want to buy a second-hand phone. You find this advert on a website. Read it, then answer the questions.</p>
<div class="blk" data-t="For sale"><p lang="en">Nexa 8 smartphone, 128 GB, black. I’m selling the phone which I used for two years before I got a work phone. It’s in very good condition: the screen, which has always had a protector on it, has no scratches. The battery life is still good (a full day of normal use). It comes with the original box and a fast charger, but not the headphones, which I lost. Price: £150, or £170 with the leather phone case. Collection only, from the town centre, where I work. Message me if you have any questions.</p></div>`,
  parts:[
   {q:'a) Why is the seller selling the phone?', opts:['The screen is scratched.','The seller now has a work phone.','The battery life is poor.','The seller has lost the headphones.'], ans:1, hint:'Look at the first relative clause in the advert.', why:'<i lang="en">the phone which I used for two years before I got a work phone</i> : le vendeur a maintenant un téléphone professionnel.'},
   {q:'b) How much does the phone cost with the case? Write the price.', lab:'Price', txt:['£170','170 pounds','one hundred and seventy pounds','a hundred and seventy pounds','one hundred seventy pounds'], hint:'There are two prices: one without the case and one with it.', why:'<i lang="en">£150, or £170 with the leather phone case</i> : 170 livres avec la coque.'},
   {q:'c) This sentence has one mistake. Write it correctly: <i lang="en">The case, that is made of leather, costs £20 extra.</i>', lab:'Correct sentence', long:true, txt:X('The case, which is',['made of leather,','leather,'],'costs',['£20 extra.','20 pounds extra.','twenty pounds extra.']), hint:'The clause between commas gives extra information.', why:'Entre virgules (relative non déterminative), jamais <i lang="en">that</i> : <i lang="en">The case, which is made of leather, costs £20 extra.</i>'},
   {q:'d) Write the compound noun in English: «&nbsp;une coque de téléphone en cuir&nbsp;».', lab:'Compound noun', txt:['a leather phone case','leather phone case'], hint:'Read the advert again: the main noun comes last, and the material comes first.', why:'<i lang="en">a leather phone case</i> : le nom principal (<i lang="en">case</i>) à la fin, ce qu’il protège (<i lang="en">phone</i>) devant, et la matière en premier.'},
   {q:'e) A friend asks what you are going to buy. Translate with <i lang="en">whose</i>: «&nbsp;C’est un téléphone dont l’écran n’a aucune rayure.&nbsp;»', lab:'Your sentence', long:true, txt:X(['It’s','It is'],'a phone whose screen',['has no scratches.','hasn’t got any scratches.','doesn’t have any scratches.','has no scratches at all.','doesn’t have a single scratch.']), hint:'« dont + nom » for possession → whose + noun.', why:'Ici « dont » marque la possession (l’écran du téléphone) : <i lang="en">It’s a phone whose screen has no scratches.</i>'}],
  sol:'<p>Le vendeur a un téléphone professionnel, d’où la vente. Prix : 150 £, ou 170 £ avec la coque en cuir (<i lang="en">a leather phone case</i>). Pas de <i lang="en">that</i> entre virgules : <i lang="en">The case, which is made of leather, costs £20 extra.</i> « dont » + possession : <i lang="en">It’s a phone whose screen has no scratches.</i></p>'},
]},

/* ======================================================================
   11. Then and now
   ====================================================================== */
{subj:'en', sem:'b1', id:'en-b1-habits', o:11, h:'Then and now', p:'Comparer la vie d’avant et celle d’aujourd’hui : <i lang="en">used to</i>, <i lang="en">would</i>, <i lang="en">be/get used to</i>, et faire une demande polie ou une réclamation (<i lang="en">Would you mind…?</i>).', steps:[
 {kind:'Écoute', h:'Grandma’s childhood',
  p:`<p>By the end of this unit, you will be able to compare life in the past and today, talk about habits you have lost or got used to, and make polite requests and complaints.</p>
<p>Chloe is doing a school project about life fifty years ago. She is interviewing her grandmother, Margaret. <b>Listen without reading</b>, then answer.</p>
<p><b>Question:</b> which sentence is true about Margaret’s childhood?</p>`,
  audio:[['Chloe','Gran, can I ask you a few questions for my project? It’s about how life has changed.'],['Margaret','Of course, love. Fire away.'],['Chloe','Where did you use to live when you were my age?'],['Margaret','In a small village in Yorkshire. We didn’t use to have a car, so I walked to school every day, three miles there and three miles back.'],['Chloe','Three miles! Every day?'],['Margaret','Every day, rain or shine. And on Saturdays, my father would take us to the market in town on the bus. He’d buy us a bag of sweets if we behaved.'],['Chloe','Did you use to have a TV?'],['Margaret','Not until I was twelve. Before that, we used to listen to the radio in the evenings. We’d all sit around it in the kitchen, which was the only warm room in the house.'],['Chloe','What’s the biggest difference today?'],['Margaret','Oh, the phones, definitely. When your grandad and I started going out, I used to write him a letter every week. Now I get twenty messages a day from the family. I’m still not used to it, to be honest.'],['Chloe','You’ll get used to it, Gran. You’re already better at video calls than Dad!']], cache:true,
  opts:['Her family drove to the market every Saturday.','She walked a long way to school every day.','She watched TV every evening as a child.','She has got used to receiving lots of messages.'], ans:1,
  why:'<i lang="en">We didn’t use to have a car, so I walked to school every day, three miles there and three miles back</i> : environ 5 km dans chaque sens. Le marché, c’était en bus ; la télévision est arrivée quand elle avait douze ans ; et elle n’est <b>pas encore</b> habituée aux messages (<i lang="en">I’m still not used to it</i>).'},

 {kind:'Vocabulaire', h:'Talking about the past and the present',
  p:`<p>Useful expressions to compare the past and the present. Tap a line to hear it, then repeat it aloud.</p>`,
  mots:[['back then / in those days','à l’époque','Back then, nobody had a mobile phone.'],['nowadays / these days','de nos jours','Nowadays, most people shop online.'],['to grow up','grandir (pendant l’enfance)','I grew up in a small village.'],['to keep in touch / to stay in touch','garder le contact','We used to keep in touch by letter.'],['to look back on','repenser à, se remémorer','I look back on those years with pleasure.'],['to miss','regretter (quelque chose qui manque)','I miss the quiet evenings.'],['to give up','arrêter, renoncer à','He gave up smoking ten years ago.'],['to take up','se mettre à (une activité)','She took up the guitar at sixty.'],['to get into the habit of','prendre l’habitude de','I’ve got into the habit of checking my phone in bed.'],['to change for the better / for the worse','changer en mieux / en pire','The town has changed for the better.'],['rain or shine','qu’il pleuve ou qu’il vente','We walked to school, rain or shine.'],['Fire away!','Vas-y, pose tes questions !','“Can I ask you something?” “Fire away!”']],
  note:'<b>Pièges :</b> <i lang="en">to miss</i> se construit à l’envers de « manquer à » : <i lang="en">I miss my village</i> = mon village me manque. Et <i lang="en">actually</i> veut dire « en fait » ; « actuellement » se dit <i lang="en">currently</i> ou <i lang="en">at the moment</i>.'},

 {kind:'Vocabulaire', h:'Complaints and polite requests',
  p:`<p>Expressions for asking politely and complaining without being rude. Tap a line to hear it, then repeat it with a friendly tone.</p>`,
  mots:[['to complain about','se plaindre de','I’d like to complain about the noise.'],['a complaint','une réclamation, une plainte','We’ve received several complaints.'],['Would you mind + -ing?','Est-ce que ça vous dérangerait de… ?','Would you mind closing the window?'],['I was wondering if you could…','Je me demandais si vous pourriez…','I was wondering if you could help me.'],['Could you possibly…?','Vous serait-il possible de… ?','Could you possibly call back later?'],['I’m sorry to bother you, but…','Désolé de vous déranger, mais…','I’m sorry to bother you, but the heating isn’t working.'],['I’m afraid…','Je regrette, mais… (mauvaise nouvelle)','I’m afraid there’s a problem with my room.'],['a refund','un remboursement','I’d like a refund, please.'],['to sort out','régler, arranger','Could you sort out the problem today?'],['to put up with','supporter, tolérer','I can’t put up with this noise any more.']],
  note:'<i lang="en">I’m afraid</i> n’exprime pas la peur ici : c’est la façon polie d’annoncer un problème ou une mauvaise nouvelle. <i lang="en">I’m afraid we’re fully booked</i> = Je regrette, nous sommes complets.'},

 {kind:'Pratique', h:'Recall: where I grew up',
  p:`<p>Write the sentence in English.</p><p><b>Question:</b> «&nbsp;J’ai grandi dans un petit village, mais de nos jours j’habite en ville.&nbsp;»</p>`, lab:'In English', long:true,
  txt:[...X('I grew up',['in a small village,','in a little village,'],'but',['nowadays','these days'],['I live in a town.','I live in a city.','I live in town.']),
       ...X('I grew up',['in a small village,','in a little village,'],'but I live in',['a town','a city','town'],['nowadays.','these days.','now.'])],
  why:'<i lang="en">I grew up in a small village, but nowadays I live in a town.</i> <i lang="en">grow up</i> est irrégulier : <i lang="en">grew up</i>. « en ville » = <i lang="en">in a town</i> ou <i lang="en">in a city</i> (une grande ville).'},

 {kind:'Grammaire', h:'Used to: past habits and states',
  p:`<p>Margaret dit <i lang="en">We didn’t use to have a car</i> et <i lang="en">We used to listen to the radio in the evenings</i>. Elle parle de choses vraies <b>régulièrement</b> ou <b>pendant longtemps</b> dans le passé, et qui ne le sont plus. Le français utilise l’imparfait (« on écoutait la radio ») ; l’anglais utilise souvent <b>used to</b>.</p>
<div class="def"><p><b>used to + base verbale</b>, identique à toutes les personnes : <i lang="en">I / she / they used to live in Leeds.</i></p><ul><li>Négation : <b>didn’t use to</b> (sans d : <i lang="en">did</i> porte déjà le passé) : <i lang="en">We didn’t use to have a car.</i> On entend aussi <i lang="en">never used to</i>.</li><li>Question : <b>Did you use to…?</b> <i lang="en">Did you use to have a TV?</i></li></ul></div>
<div class="idea"><p><i lang="en">Used to</i> souligne le <b>contraste avec aujourd’hui</b> : c’était vrai, ce ne l’est plus. Il marche pour les <b>actions répétées</b> (<i lang="en">I used to walk to school</i>) et pour les <b>états</b> qui ont duré (<i lang="en">I used to have long hair, She used to live in Paris</i>).</p></div>
<div class="ex"><p><i lang="en">I used to play the piano, but I gave up at fifteen.</i> = Je jouais du piano, mais j’ai arrêté à quinze ans.<br><i lang="en">There used to be a cinema here.</i> = Il y avait un cinéma ici (autrefois).</p></div>
<div class="warn"><p>Pièges des francophones : <b>used to n’existe pas au présent</b>. Pour une habitude actuelle : <i lang="en">I usually walk to work</i>, pas <i lang="en"><s>I use to walk to work</s></i>. Pas de <i lang="en">used to</i> pour un fait unique ou un nombre de fois précis : <i lang="en">I went to Japan three times</i>. Et « j’avais l’habitude de jouer » ne se calque pas en <i lang="en"><s>I was used to play</s></i> : on dit <i lang="en">I used to play</i>.</p></div>`,
  audio:'We used to listen to the radio in the evenings. We didn’t use to have a car. Did you use to have a TV? There used to be a cinema here.'},

 {kind:'Grammaire', h:'Would for repeated actions in the past',
  p:`<p>Margaret raconte aussi : <i lang="en">On Saturdays, my father <b>would</b> take us to the market. He<b>’d</b> buy us a bag of sweets.</i> Ici, <b>would</b> n’a rien d’un conditionnel : il décrit une <b>action répétée</b> dans le passé, comme <i lang="en">used to</i>. On le trouve surtout dans les récits et les souvenirs, souvent avec un peu de nostalgie.</p>
<div class="def"><p><b>would (’d) + base verbale</b> pour une action qui se répétait dans le passé : <i lang="en">Every summer, we would go to my uncle’s farm.</i> Le contexte (une période passée, <i lang="en">every…, on Saturdays, when I was a child</i>) doit déjà situer la scène dans le passé.</p></div>
<div class="idea"><p>Dans un souvenir, on pose souvent le cadre avec <i lang="en">used to</i>, puis on continue avec <i lang="en">would</i> pour ne pas répéter : <i lang="en">We used to spend the evenings in the kitchen. We’d sit around the radio and my mother would knit.</i></p></div>
<div class="ex"><p>Action répétée : <i lang="en">used to</i> ou <i lang="en">would</i> : <i lang="en">My grandad used to / would tell us stories.</i><br>État (<i lang="en">be, have, live, like, know</i>…) : seulement <i lang="en">used to</i> : <i lang="en">He used to have a beard</i>, pas <i lang="en"><s>He would have a beard</s></i>.</p></div>
<div class="warn"><p>Piège : sans repère passé, <i lang="en">I would walk to school</i> se comprend comme un conditionnel (« j’irais à pied »). Pose d’abord le cadre : <i lang="en">When I was a child, I would walk to school.</i> Et pour un fait unique, c’est le prétérit : <i lang="en">One day, my father <b>bought</b> a television.</i></p></div>`,
  audio:'On Saturdays, my father would take us to the market. He’d buy us a bag of sweets. We’d all sit around the radio in the kitchen.'},

 {kind:'Méthode', h:'Choosing between used to, would and the past simple',
  p:`<p><b>Quand :</b> dès que tu racontes ta vie d’avant, un souvenir d’enfance ou une ville qui a changé. <b>Pourquoi :</b> ces trois formes parlent du passé, mais pas de la même chose : un fait <b>unique</b>, une <b>habitude</b>, un <b>état</b>. <b>Comment :</b> pose-toi trois questions.</p>
<ol><li>Est-ce arrivé <b>une fois</b> (ou un nombre de fois précis) ? → <b>prétérit</b> : <i lang="en">I moved to London in 2010.</i></li><li>Est-ce une <b>action répétée</b> qui n’existe plus ? → <b>used to</b> ou <b>would</b> (would seulement si le passé est déjà posé).</li><li>Est-ce un <b>état</b> qui a duré (<i lang="en">be, have, live, like, know, believe</i>…) ? → <b>used to</b> (ou le prétérit), jamais <i lang="en">would</i>.</li></ol>
<p>Le prétérit simple reste toujours possible pour une habitude (<i lang="en">I walked to school every day</i>) ; <i lang="en">used to</i> souligne seulement que c’est fini.</p>`,
  demo:{enonce:'Mets les verbes à la bonne forme : <i lang="en">When I was a student, I (live) in a tiny flat. Every morning, I (cycle) to university. One day, I (meet) my future wife on the bus.</i>',
   etapes:[{f:'<i lang="en">live</i> : un état qui a duré → <i lang="en">I <b>used to live</b> in a tiny flat.</i>',w:'<i lang="en">would live</i> est impossible : <i lang="en">live</i> décrit une situation, pas une action répétée.'},
    {f:'<i lang="en">cycle</i> : une action répétée (<i lang="en">every morning</i>), et le passé est déjà posé → <i lang="en">I <b>would cycle</b></i> ou <i lang="en">I <b>used to cycle</b></i>.',w:'Les deux sont justes ; <i lang="en">would</i> évite de répéter <i lang="en">used to</i>.'},
    {f:'<i lang="en">meet</i> : un événement unique (<i lang="en">one day</i>) → <i lang="en">I <b>met</b> my future wife.</i>',w:'Ni <i lang="en">used to</i> ni <i lang="en">would</i> : ce n’est arrivé qu’une fois.'}],
   conclusion:'<i lang="en">When I was a student, I used to live in a tiny flat. Every morning, I would cycle to university. One day, I met my future wife on the bus.</i>'}},

 {kind:'Pratique', h:'Practice: not true any more',
  p:`<p>Write one sentence with <i lang="en">used to</i> that sums up the two sentences.</p><p><b>Question:</b> <i lang="en">Tom lived in Glasgow when he was younger. He doesn’t live there now.</i></p>`, lab:'Your sentence',
  txt:['Tom used to live in Glasgow.','He used to live in Glasgow.','Tom used to live in Glasgow when he was younger.','Tom used to live there.'],
  why:'<i lang="en">Tom used to live in Glasgow.</i> C’est un état passé qui n’est plus vrai : <i lang="en">used to</i> + base verbale (<i lang="en">live</i>, pas <i lang="en">lived</i>).'},

 {kind:'Pratique', h:'Practice: ask about the past',
  p:`<p>Write the question with <i lang="en">use to</i>. Start with <i lang="en">Did</i>.</p><p><b>Question:</b> ask your grandmother if she had a phone when she was young.</p>`, lab:'Your question',
  txt:X('Did you use to have',['a phone','a telephone'],['when you were young?','when you were a child?','when you were younger?','when you were little?','']),
  why:'<i lang="en">Did you use to have a phone when you were young?</i> Après <i lang="en">did</i>, on écrit <i lang="en">use to</i>, sans d : <i lang="en">did</i> porte déjà le passé.'},

 {kind:'Pratique', h:'Practice: would or used to?',
  p:`<p>Three sentences are correct and one is not.</p><p><b>Question:</b> which sentence is <b>wrong</b>?</p>`,
  opts:['When we were kids, we would play in the street until dark.','My grandparents used to live on a farm.','My grandmother would have very long hair.','There used to be a bakery on this corner.'], ans:2,
  why:'<i lang="en">have long hair</i> est un <b>état</b>, pas une action répétée : seul <i lang="en">used to</i> marche. <i lang="en">My grandmother used to have very long hair.</i>'},

 {kind:'Grammaire', h:'Be used to and get used to',
  p:`<p>À la fin du dialogue, Margaret dit <i lang="en">I’m still not used to it</i> et Chloe répond <i lang="en">You’ll get used to it</i>. Le même mot <i lang="en">used</i>, mais un tout autre sens que <i lang="en">used to + verbe</i> : il s’agit d’être <b>habitué</b> à quelque chose, ou de <b>s’y habituer</b>.</p>
<div class="def"><ul><li><b>be used to + nom / pronom / verbe en -ing</b> = être habitué à : <i lang="en">I’m used to the noise. I’m used to getting up early.</i></li><li><b>get used to + nom / pronom / verbe en -ing</b> = s’habituer à (le changement) : <i lang="en">It took me months to get used to driving on the left.</i></li></ul><p>Ici, <b>to</b> est une préposition : il est suivi d’un nom ou d’un verbe en <b>-ing</b>, jamais de la base verbale. <i lang="en">be</i> et <i lang="en">get</i> se conjuguent à tous les temps : <i lang="en">I wasn’t used to…, I’ve got used to…, you’ll get used to…</i></p></div>
<div class="idea"><p>Compare : <i lang="en">I <b>used to work</b> at night</i> = je travaillais la nuit (avant, plus maintenant). <i lang="en">I’m <b>used to working</b> at night</i> = j’ai l’habitude de travailler la nuit (aujourd’hui, ça ne me gêne pas).</p></div>
<div class="ex"><p><i lang="en">She’s from Spain, so she isn’t used to the cold.</i><br><i lang="en">Don’t worry, you’ll soon get used to your new job.</i><br><i lang="en">Have you got used to living alone?</i></p></div>
<div class="warn"><p>Le piège n° 1 : <i lang="en"><s>I’m used to work late</s></i> → <i lang="en">I’m used to <b>working</b> late</i>. Et ne confonds pas avec le verbe <i lang="en">use</i> (utiliser) au présent : <i lang="en">I use my phone a lot</i>.</p></div>`,
  audio:'I’m still not used to it. You’ll get used to it. I’m used to getting up early. It took me months to get used to driving on the left.'},

 {kind:'Méthode', h:'Used to do or be used to doing?',
  p:`<p><b>Quand :</b> chaque fois que tu vois ou veux dire <i lang="en">used to</i>. <b>Pourquoi :</b> les deux constructions se ressemblent, mais le mot qui précède et celui qui suit révèlent le sens. <b>Comment :</b></p>
<ol><li>Regarde <b>devant</b> : y a-t-il <i lang="en">be</i> ou <i lang="en">get</i> conjugué (<i lang="en">am, is, was, ’ve got, will get</i>…) ? Si oui, c’est « être habitué » ou « s’habituer ».</li><li>Regarde <b>derrière</b> : avec <i lang="en">be/get used to</i>, mets un nom ou un verbe en <b>-ing</b>. Avec <i lang="en">used to</i> seul, mets la <b>base verbale</b>.</li><li>Vérifie le sens : habitude passée finie (avant, plus maintenant) ou familiarité (c’est normal pour moi) ?</li></ol>`,
  demo:{enonce:'Traduis : « Avant, je conduisais une petite voiture, donc je n’ai pas l’habitude de garer un grand van. »',
   etapes:[{f:'« Avant, je conduisais » : une habitude finie → <i lang="en">I <b>used to drive</b> a small car</i>.',w:'Pas de <i lang="en">be</i> devant, base verbale derrière.'},
    {f:'« je n’ai pas l’habitude de garer » : familiarité → <i lang="en">I’m not used to</i> + verbe en -ing.',w:'<i lang="en">be</i> est conjugué devant (<i lang="en">am not</i>), donc un verbe en -ing derrière.'},
    {f:'<i lang="en">…so I’m not used to <b>parking</b> a big van.</i>',w:'<i lang="en">park</i> → <i lang="en">parking</i>, car <i lang="en">to</i> est ici une préposition.'}],
   conclusion:'<i lang="en">I used to drive a small car, so I’m not used to parking a big van.</i>'}},

 {kind:'Pratique', h:'Practice: be used to',
  p:`<p>Translate into English.</p><p><b>Question:</b> «&nbsp;Je n’ai pas l’habitude de conduire à gauche.&nbsp;»</p>`, lab:'In English',
  txt:X('I’m not used to driving on the',['left.','left-hand side.','left side of the road.','left-hand side of the road.']),
  why:'<i lang="en">I’m not used to driving on the left.</i> « avoir l’habitude de » au présent = <i lang="en">be used to</i> + verbe en <b>-ing</b>. <i lang="en"><s>I don’t use to drive</s></i> n’existe pas.'},

 {kind:'Pratique', h:'Practice: get used to',
  p:`<p>Complete the sentence with <i lang="en">get used to</i> and the verb in brackets (three words in total).</p><p><b>Question:</b> <i lang="en">When I moved to Norway, it took me a whole winter to ___ (live) with so little daylight.</i></p>`, lab:'Three words', txt:['get used to living'],
  why:'<i lang="en">it took me a whole winter to get used to living with so little daylight</i> : <i lang="en">get used to</i> exprime le changement (s’habituer), et <i lang="en">to</i> est suivi de <i lang="en">-ing</i>.'},

 {kind:'Grammaire', h:'Polite requests and complaints',
  p:`<p>Pour demander un service ou se plaindre en anglais, la politesse passe par des formules <b>indirectes</b>. Un impératif sec (<i lang="en">Turn the music down.</i>) ou même <i lang="en">Can you…?</i> peut sembler brusque à un Britannique, surtout avec un inconnu.</p>
<div class="def"><ul><li><b>Would you mind + verbe en -ing?</b> <i lang="en">Would you mind turning the music down?</i> Pour toi-même : <b>Would you mind if I + prétérit?</b> <i lang="en">Would you mind if I opened the window?</i></li><li><b>Could you (possibly) + base verbale?</b> <i lang="en">Could you possibly move your car?</i></li><li><b>I was wondering if you could + base verbale.</b> Très poli, pour une vraie faveur.</li><li>Pour se plaindre : <i lang="en">I’m sorry to bother you, but… / I’m afraid there’s a problem with… / I’d like to complain about…</i></li></ul></div>
<div class="idea"><p>La réclamation britannique typique est douce en surface : on s’excuse d’abord, on décrit le problème, puis on propose une solution sous forme de question. <i lang="en">I’m sorry to bother you, but the music is quite loud. Would you mind turning it down a bit?</i></p></div>
<div class="warn"><p>Pièges : <i lang="en">Would you mind <s>to turn</s></i> → <i lang="en">turning</i>. Et attention à la réponse : <i lang="en">mind</i> = « être gêné par ». Pour accepter, on dit <b>No, not at all</b> ou <b>Of course not</b> (non, ça ne me dérange pas). Répondre <i lang="en">Yes</i> signifie « oui, ça me dérange » !</p></div>`,
  audio:[['Neighbour','I’m sorry to bother you, but the music is quite loud. Would you mind turning it down a bit?'],['Student','Oh, sorry! No, not at all.']]},

 {kind:'Pratique', h:'Practice: make it polite',
  p:`<p>Rewrite the request politely with <i lang="en">Would you mind…?</i></p><p><b>Question:</b> <i lang="en">Close the door.</i></p>`, lab:'Your request',
  txt:['Would you mind closing the door?','Would you mind closing the door, please?','Would you mind shutting the door?'],
  why:'<i lang="en">Would you mind closing the door?</i> Après <i lang="en">mind</i>, le verbe prend <b>-ing</b>. Réponse si on accepte : <i lang="en">No, not at all.</i>'},

 {kind:'Prononciation', h:'Pronouncing used to',
  p:`<p>Dans <i lang="en">used to</i> (habitude passée) comme dans <i lang="en">be used to</i>, le <i lang="en">s</i> se prononce <b>/s/</b> et non /z/, et le <i lang="en">d</i> disparaît : on dit « youss-te » /ˈjuːstə/, comme un seul mot, avec un <i lang="en">to</i> faible /tə/.</p>
<div class="def"><p><i lang="en">used to</i> /ˈjuːstə/ : <i lang="en">I used to live here.</i><br>Le verbe <i lang="en">use</i> (utiliser) se dit /juːz/, et au passé <i lang="en">used</i> /juːzd/ : <i lang="en">I used a knife.</i></p></div>
<div class="warn"><p>Les francophones prononcent souvent « youzed tou » en détachant tout : c’est le signe immédiat d’un accent. Pense « youss-te », vite, avec l’accent sur la première syllabe.</p></div>
<p>Listen, then repeat the sentence.</p>`,
  dire:'We used to walk to school, rain or shine, but I’m used to driving now.'},

 {kind:'Lecture', h:'How my town has changed',
  p:`<p>Read this blog post. You can also listen to it.</p>
<div class="blk" data-t="Blog: Brightwell, then and now"><p lang="en">When I was growing up in Brightwell in the 1990s, the high street was the centre of everything. There used to be a butcher’s, two bakeries, a bookshop and a cinema where my friends and I would spend every Saturday afternoon. People used to know each other by name, and the shopkeepers would always ask about your family.</p><p lang="en">Today, most of those shops have gone. The cinema is a gym, and the bookshop became a phone shop, which closed last year. People shop online or drive to the supermarket on the ring road. At first, I hated the changes. I wasn’t used to seeing so many empty windows, and I missed the noise of the market.</p><p lang="en">But not everything has changed for the worse. The old bus station is now a park, and there’s a new library with free wifi, where teenagers do their homework after school. There are more cafés than ever, and some empty shops are being turned into flats for young people. I’ve got used to the new Brightwell, and in some ways I prefer it. I just wish we still had a cinema.</p></div>
<p><b>Question:</b> what does the writer think of the town today?</p>`,
  audio:'When I was growing up in Brightwell in the 1990s, the high street was the centre of everything. There used to be a butcher’s, two bakeries, a bookshop and a cinema where my friends and I would spend every Saturday afternoon. People used to know each other by name, and the shopkeepers would always ask about your family. Today, most of those shops have gone. The cinema is a gym, and the bookshop became a phone shop, which closed last year. People shop online or drive to the supermarket on the ring road. At first, I hated the changes. I wasn’t used to seeing so many empty windows, and I missed the noise of the market. But not everything has changed for the worse. The old bus station is now a park, and there’s a new library with free wifi, where teenagers do their homework after school. There are more cafés than ever, and some empty shops are being turned into flats for young people. I’ve got used to the new Brightwell, and in some ways I prefer it. I just wish we still had a cinema.',
  opts:['Everything has changed for the worse.','The writer is still not used to the changes and wants to leave.','The writer has got used to the town and likes some changes, but misses the cinema.','The town is better than before in every way.'], ans:2,
  why:'<i lang="en">I’ve got used to the new Brightwell, and in some ways I prefer it. I just wish we still had a cinema.</i> Au début, l’auteur n’était pas habitué (<i lang="en">I wasn’t used to…</i>), mais c’est fini. Repère aussi <i lang="en">there used to be</i> (état) et <i lang="en">would spend</i> (habitude).'},

 {kind:'Dictée', h:'Dictation: memories',
  p:'Listen and write the sentence exactly. Be careful with the spelling of <i lang="en">use</i> after <i lang="en">didn’t</i>.',
  dictee:'We didn’t use to have a television, so we would play outside until it got dark.',
  why:'<i lang="en">didn’t use to</i> s’écrit sans d ; <i lang="en">would play</i> décrit une action répétée dans le passé.'},

 {kind:'Oral', h:'Then and now: your life',
  p:`<p>Speak for about one minute. Compare your life ten years ago and today: where you used to live, what you used to do in your free time, something you would do every weekend, something you have got used to, and something you are still not used to.</p>`,
  oral:{modele:'Ten years ago, I used to live with my parents in a small town near Lausanne. I didn’t use to work, of course: I was still at school. Every Saturday, my friends and I would take the train to the city and spend the afternoon in the same café. I used to be quite shy, but that has changed. Now I live in Geneva and I work in an office. At first, I wasn’t used to getting up at six, but I’ve got used to it. The thing I’m still not used to is the price of everything!',
   criteres:['I used used to for a past habit or state','I used would for a repeated action, after setting the scene','I used be used to or get used to + -ing or a noun','I compared the past and the present (now, nowadays, these days)','I pronounced used to as « youss-te »']}},

 {kind:'Écriture', h:'Write a polite complaint',
  p:'New neighbours moved into the flat above yours a month ago. They often play loud music late at night. Write a polite note to them (about 120 words). Explain who you are and what life used to be like, describe the problem precisely, make at least two polite requests, and finish in a friendly way.',
  ecrire:{min:110, modele:'Dear neighbours, I hope you’re settling in well. I’m sorry to bother you, but I wanted to mention something. I live in the flat below yours, and I start work at six, so I usually go to bed at about ten. The previous tenants were very quiet, so I’m used to peaceful evenings. Since you moved in, though, there has often been loud music after midnight, and last night I hardly slept. I know you’re still getting used to the building, and the walls are quite thin. Would you mind turning the music down after ten on weekdays? And could you possibly let me know when you’re having a party, so I can plan ahead? Thanks very much for understanding, and do knock if you ever need anything! Best wishes, Anna (Flat 2)',
   criteres:[{t:'I started politely (Dear…, I’m sorry to bother you…)', re:'\\b(dear|sorry|hope|hello|hi)\\b'},{t:'I used Would you mind + -ing', re:'would you mind \\w+ing'},{t:'I made another polite request (Could you possibly…, I was wondering if…)', re:'\\b(could you|i was wondering)\\b'},{t:'I used used to or be/get used to', re:'\\bused to\\b'},'I described the problem precisely (what, when, how often)','I finished in a friendly way']}},

 {kind:'Récapitulatif', h:'Ce qu’il faut retenir',
  p:`<div class="keep"><ul><li><b>used to + base verbale</b> : habitude ou état passé qui n’existe plus. Négation <i lang="en">didn’t use to</i>, question <i lang="en">Did you use to…?</i> Pas de présent : <i lang="en">I usually…</i>. Pas pour un fait unique ni un nombre de fois précis.</li><li><b>would + base verbale</b> : action répétée dans le passé, une fois le cadre posé. Jamais pour un état (<i lang="en"><s>He would have a beard</s></i>).</li><li>Fait unique → <b>prétérit</b> : <i lang="en">One day, I met…</i></li><li><b>be used to + nom / -ing</b> = être habitué à ; <b>get used to + nom / -ing</b> = s’habituer à. <i lang="en">I’m used to working late. You’ll get used to it.</i></li><li>Demandes polies : <i lang="en">Would you mind + -ing? Would you mind if I + prétérit? Could you possibly…? I was wondering if you could…</i> Accepter : <i lang="en">No, not at all.</i></li><li>Réclamation : <i lang="en">I’m sorry to bother you, but… I’m afraid there’s a problem with… I’d like to complain about…</i></li><li>Prononciation : <i lang="en">used to</i> = « youss-te » /ˈjuːstə/.</li></ul></div>`},

 {kind:'Mission', h:'A complaint at the hotel',
  p:'You are staying in a hotel in Edinburgh. In the lobby, you hear another guest talking to the receptionist. Listen to the conversation, then answer the questions one by one. You can listen again at any time.',
  audio:[['Guest','Good evening. I’m sorry to bother you, but I’m afraid there’s a problem with my room.'],['Receptionist','Oh dear. What seems to be the problem?'],['Guest','Well, the air conditioning is making a terrible noise, and the window won’t close properly. I’m used to sleeping with a bit of noise, but this is like sleeping next to a motorway.'],['Receptionist','I’m very sorry about that. Which room are you in?'],['Guest','Room three one four.'],['Receptionist','I’m afraid we can’t repair it tonight, because the technician has gone home. But I can move you to a room on the fifth floor, which is much quieter.'],['Guest','That would be great. Would you mind sending someone to help with my suitcase? It’s really heavy.'],['Receptionist','Not at all. And we’ll take ten per cent off your bill for the inconvenience.'],['Guest','That’s very kind. Thank you.']], cache:true,
  parts:[
   {q:'a) What are the two problems with the room?', opts:['The heating and the TV','The shower and the window','The air conditioning and the window','The street noise and the lights'], ans:2, hint:'The guest mentions one machine and one part of the room.', why:'<i lang="en">The air conditioning is making a terrible noise, and the window won’t close properly.</i>'},
   {q:'b) What does the receptionist offer?', opts:['To repair the room tonight','A quieter room and ten per cent off the bill','A free dinner and a new room','A full refund'], ans:1, hint:'There are two things: a change and a discount.', why:'Une chambre plus calme au cinquième étage (<i lang="en">a room on the fifth floor, which is much quieter</i>) et 10 % de réduction (<i lang="en">ten per cent off your bill</i>).'},
   {q:'c) The guest asks for help with the suitcase. Write the polite question exactly as you hear it.', lab:'The question', long:true, txt:['Would you mind sending someone to help with my suitcase?','Would you mind sending someone to help me with my suitcase?'], hint:'It starts with “Would you mind” and the next verb ends in -ing.', why:'<i lang="en">Would you mind sending someone to help with my suitcase?</i> : <i lang="en">mind</i> + verbe en -ing.'},
   {q:'d) The receptionist answers “Not at all.” What does she mean?', opts:['No, I refuse.','Yes, it’s a problem for me.','I don’t understand the question.','No problem, I’ll do it.'], ans:3, hint:'Think about what “mind” means.', why:'<i lang="en">Would you mind…?</i> = ça vous dérange ? <i lang="en">Not at all</i> = pas du tout, donc elle accepte.'},
   {q:'e) Now you are the guest. Say that you are not used to sleeping with the window open.', lab:'Your sentence', long:true, txt:X('I’m not used to sleeping with',['the window open.','the windows open.','an open window.','open windows.']), hint:'be used to + -ing.', why:'<i lang="en">I’m not used to sleeping with the window open.</i> <i lang="en">be used to</i> + verbe en -ing : <i lang="en">sleeping</i>, pas <i lang="en">sleep</i>.'}],
  sol:'<p lang="en">Guest: I’m sorry to bother you, but I’m afraid there’s a problem with my room… the air conditioning is making a terrible noise, and the window won’t close properly. – Receptionist: … I can move you to a room on the fifth floor, which is much quieter. – Guest: Would you mind sending someone to help with my suitcase? – Not at all. And we’ll take ten per cent off your bill.</p><p>Le client se plaint poliment : excuse (<i lang="en">I’m sorry to bother you</i>), problème (<i lang="en">I’m afraid…</i>), puis demande avec <i lang="en">Would you mind + -ing</i>. <i lang="en">Not at all</i> veut dire qu’on accepte.</p>'},

 {kind:'Mission', h:'An email from an old friend',
  p:`<p>Your friend Jake moved from Bristol to Canada five years ago. Read his email, then answer the questions.</p>
<div class="blk" data-t="Email"><p lang="en">Hi Sam, it’s been ages! I can’t believe it’s five years since I moved to Toronto. Do you remember how we used to spend every Friday night at that terrible karaoke bar? I still can’t sing, by the way.</p><p lang="en">Life here is very different. I used to cycle everywhere in Bristol, but in winter it’s minus twenty here, so I take the underground. It took me a long time to get used to the cold, and I’m still not used to how polite everyone is: Canadians say sorry even more than the English! Last winter, my neighbours and I would play ice hockey on the frozen lake every Sunday. Great fun, but I fell over about a hundred times.</p><p lang="en">Anyway, I’m writing because I’m coming back to Bristol for a conference in June. I was wondering if I could stay at your place for three nights? I’d completely understand if it’s not possible. Write soon! Jake</p></div>`,
  parts:[
   {q:'a) What did Jake and Sam use to do on Friday nights?', opts:['Play ice hockey','Go to a karaoke bar','Cycle around Bristol','Watch films at the cinema'], ans:1, hint:'Look at the first paragraph.', why:'<i lang="en">we used to spend every Friday night at that terrible karaoke bar</i>.'},
   {q:'b) How did Jake use to travel in Bristol? Answer with a full sentence with <i lang="en">used to</i>.', lab:'Your sentence', txt:X(['He used to','Jake used to'],['cycle everywhere.','cycle.','go everywhere by bike.','go by bike.','ride his bike everywhere.','travel by bike.','cycle everywhere in Bristol.']), hint:'used to + base form of the verb.', why:'<i lang="en">He used to cycle everywhere.</i> Habitude passée qui n’existe plus (à Toronto, il prend le métro).'},
   {q:'c) What does Jake want from Sam?', opts:['To visit him in Toronto','To find him a cheap hotel','To go to the conference with him','To stay at Sam’s place for three nights'], ans:3, hint:'Look for the polite request in the last paragraph.', why:'<i lang="en">I was wondering if I could stay at your place for three nights?</i> : une demande très polie.'},
   {q:'d) Rewrite Jake’s request with <i lang="en">Would you mind if I…?</i>', lab:'Your request', long:true, txt:X('Would you mind if I stayed',['at your place','with you','at your flat','at your house'],['for three nights?','for 3 nights?','']), hint:'Would you mind if I + past simple.', why:'<i lang="en">Would you mind if I stayed at your place for three nights?</i> Après <i lang="en">Would you mind if I</i>, on met le prétérit (<i lang="en">stayed</i>), même si on parle de l’avenir.'},
   {q:'e) Write a sentence about Jake and the cold: «&nbsp;Il lui a fallu longtemps pour s’habituer au froid.&nbsp;»', lab:'Your sentence', long:true, txt:X(['It took him','It took Jake'],['a long time','ages','a long while'],'to get used to the cold.'), hint:'It took him… to get used to + noun.', why:'<i lang="en">It took him a long time to get used to the cold.</i> <i lang="en">get used to</i> = s’habituer, suivi ici d’un nom.'}],
  sol:'<p>Jake et Sam allaient au karaoké tous les vendredis (<i lang="en">used to spend</i>). À Bristol, Jake allait partout à vélo : <i lang="en">He used to cycle everywhere.</i> Il lui a fallu longtemps pour s’habituer au froid : <i lang="en">It took him a long time to get used to the cold.</i> Sa demande : <i lang="en">I was wondering if I could stay…</i> = <i lang="en">Would you mind if I stayed at your place for three nights?</i> Note aussi <i lang="en">would play</i> : une action répétée l’hiver dernier.</p>'},
]},

/* ======================================================================
   12. Lifestyle
   ====================================================================== */
{subj:'en', sem:'b1', id:'en-b1-lifestyle', o:12, h:'Lifestyle', p:'Parler de sa santé et de son mode de vie, et donner des conseils nuancés : les quantificateurs (<i lang="en">few, a little, plenty of, hardly any</i>), <i lang="en">ought to</i>, <i lang="en">had better</i>, et les phrasal verbs de la santé et du sport.', steps:[
 {kind:'Écoute', h:'A new start',
  p:`<p>By the end of this unit, you will be able to talk about your lifestyle, describe quantities precisely, and give advice and warnings at the right strength.</p>
<p>Ben meets his friend Nadia, who looks very well. He asks her for advice. <b>Listen without reading</b>, then answer.</p>
<p><b>Question:</b> what is Nadia’s first piece of advice?</p>`,
  audio:[['Ben','Nadia, you look great. Have you been on holiday?'],['Nadia','No, I’ve just changed a few things. I took up swimming in January, and I’ve cut down on sugar.'],['Ben','I really ought to do something. I spend all day at my desk, I get hardly any exercise, and I eat far too many takeaways.'],['Nadia','How much sleep do you get?'],['Ben','Not much. Five hours, maybe six. I’m always on my phone until late.'],['Nadia','Well, that’s the first thing. You’d better put your phone in another room at night, or you’ll never sleep properly.'],['Ben','Fair enough. What about exercise? I haven’t got much time.'],['Nadia','You don’t need much. There are plenty of short workouts online, twenty minutes or less. Or just walk to work. It’s only a few kilometres.'],['Ben','I tried running last year, but I gave up after a week. My knees hurt.'],['Nadia','Did you warm up first?'],['Ben','Er… no. I just put on my trainers and went.'],['Nadia','There you go. Start slowly, warm up properly, and don’t try to do too much too soon. A little exercise every day is better than a lot once a month.']], cache:true,
  opts:['Join a gym and train every day','Keep his phone out of the bedroom at night','Stop eating sugar completely','Start running again tomorrow'], ans:1,
  why:'<i lang="en">You’d better put your phone in another room at night, or you’ll never sleep properly.</i> Ensuite, elle lui conseille des séances courtes, la marche, et de bien s’échauffer (<i lang="en">warm up properly</i>).'},

 {kind:'Vocabulaire', h:'Healthy habits',
  p:`<p>Useful collocations to talk about lifestyle and health. Learn them as blocks: the verb and the noun go together. Tap a line to hear it.</p>`,
  mots:[['a healthy lifestyle','un mode de vie sain','She has a very healthy lifestyle.'],['a balanced diet','une alimentation équilibrée','A balanced diet includes plenty of vegetables.'],['to get enough sleep','dormir suffisamment','Teenagers rarely get enough sleep.'],['to do exercise / to exercise','faire de l’exercice','I try to do some exercise every day.'],['to keep fit / to stay in shape','rester en forme','Swimming is a great way to keep fit.'],['to go for a run / a walk','aller courir / se promener','Let’s go for a walk after lunch.'],['junk food / a takeaway','la malbouffe / un plat à emporter','We eat far too many takeaways.'],['to skip breakfast','sauter le petit-déjeuner','I often skip breakfast when I’m late.'],['to be short of time','manquer de temps','I’m always short of time in the morning.'],['a sedentary job','un travail sédentaire','People with sedentary jobs should move every hour.'],['to lose / to put on weight','perdre / prendre du poids','He’s put on weight since he stopped cycling.']],
  note:'<b>Pièges :</b> « faire du sport » = <i lang="en">do sport</i> (britannique) ou <i lang="en">play sports</i>, jamais <i lang="en">make sport</i>. <i lang="en">diet</i> désigne ce qu’on mange en général (<i lang="en">a healthy diet</i>) ; « être au régime » = <i lang="en">be on a diet</i>. Et le « footing » n’est pas anglais : <i lang="en">go running</i> ou <i lang="en">go jogging</i>.'},

 {kind:'Vocabulaire', h:'Phrasal verbs for health and sport',
  p:`<p>Native speakers use phrasal verbs all the time to talk about health and sport. Tap a line to hear it, then repeat the example.</p>`,
  mots:[['to work out','s’entraîner (salle de sport)','I work out at the gym three times a week.'],['to warm up / to cool down','s’échauffer / récupérer en douceur','Always warm up before you run.'],['to take up','se mettre à (un sport, une activité)','I took up swimming in January.'],['to give up','arrêter, abandonner','She gave up smoking last year.'],['to cut down on','réduire (sa consommation de)','I’m trying to cut down on sugar.'],['to cut out','supprimer (de son alimentation)','The doctor told me to cut out salt.'],['to get over','se remettre de','It took me two weeks to get over the flu.'],['to keep up with','suivre le rythme de','I can’t keep up with the others in my running club.'],['to sign up for','s’inscrire à','I’ve signed up for a ten-kilometre race.'],['to burn off','brûler, éliminer (des calories)','A long walk burns off a lot of calories.']],
  note:'<i lang="en">work out</i> a aussi le sens de « trouver, comprendre » : <i lang="en">I can’t work out the answer.</i> Le nom s’écrit en un mot : <i lang="en">a twenty-minute workout</i>. Et <i lang="en">work out</i> ne veut jamais dire « travailler dehors » !'},

 {kind:'Pratique', h:'Recall: Nadia’s changes',
  p:`<p>Write the sentence in English. Use two phrasal verbs from the list.</p><p><b>Question:</b> «&nbsp;Je me suis mis à la natation et j’ai réduit le sucre.&nbsp;»</p>`, lab:'In English', long:true,
  txt:X(['I’ve taken up','I took up'],'swimming and',['I’ve cut down on','I cut down on','cut down on','I’ve reduced','reduced'],'sugar.'),
  why:'<i lang="en">I’ve taken up swimming and cut down on sugar.</i> <i lang="en">take up</i> = commencer une activité ; <i lang="en">cut down on</i> = réduire. Le prétérit (<i lang="en">I took up…</i>) est juste aussi si on pense au moment précis.'},

 {kind:'Grammaire', h:'Few, a few, little, a little',
  p:`<p>Nadia dit <i lang="en">It’s only <b>a few</b> kilometres</i> et <i lang="en"><b>A little</b> exercise every day is better than a lot once a month</i>. Pour les petites quantités, l’anglais a quatre mots très proches. Le choix dépend de deux questions : le nom est-il dénombrable ou non ? L’idée est-elle positive ou négative ?</p>
<div class="def"><ul><li>Avec un nom <b>dénombrable pluriel</b> (<i lang="en">kilometres, friends, minutes</i>) : <b>a few</b> = quelques (idée positive : ça suffit) ; <b>few</b> = peu de (idée négative : pas assez).</li><li>Avec un nom <b>indénombrable</b> (<i lang="en">time, sugar, exercise, money, advice</i>) : <b>a little</b> = un peu de (positif) ; <b>little</b> = peu de (négatif).</li></ul></div>
<div class="idea"><p>Le petit <b>a</b> change tout : il fait passer de « presque rien » à « un peu, et c’est bien ». <i lang="en">I have a few friends in Leeds</i> = j’ai quelques amis (je ne suis pas seul). <i lang="en">I have few friends in Leeds</i> = j’ai peu d’amis (je me sens seul). À l’oral courant, <i lang="en">few</i> et <i lang="en">little</i> seuls sonnent un peu formels : on dit souvent <i lang="en">not many</i>, <i lang="en">not much</i>, ou <i lang="en">very few</i>, <i lang="en">very little</i>.</p></div>
<div class="ex"><p><i lang="en">Add a little salt.</i> (un peu de sel) · <i lang="en">There’s little hope.</i> (il y a peu d’espoir)<br><i lang="en">I’ll be ready in a few minutes.</i> · <i lang="en">Few people know this.</i> (peu de gens le savent)</p></div>
<div class="warn"><p>Pièges : <i lang="en"><s>a few time</s></i> → <i lang="en">a little time</i> (<i lang="en">time</i> est indénombrable) ; <i lang="en"><s>a little friends</s></i> → <i lang="en">a few friends</i> ; <i lang="en"><s>a few advices</s></i> → <i lang="en">a little advice</i> (<i lang="en">advice</i> est indénombrable). <i lang="en">a little</i> peut aussi porter sur un adjectif : <i lang="en">I’m a little tired</i>.</p></div>`,
  audio:'It’s only a few kilometres. A little exercise every day is better than a lot once a month. I have a few friends in Leeds. I have few friends in Leeds.'},

 {kind:'Grammaire', h:'Plenty of, hardly any and other quantifiers',
  p:`<p>Ben dit <i lang="en">I get <b>hardly any</b> exercise</i>, et Nadia répond <i lang="en">There are <b>plenty of</b> short workouts online</i>. Ces deux expressions, très fréquentes, nuancent bien mieux que <i lang="en">a lot</i> ou <i lang="en">not much</i>.</p>
<div class="def"><ul><li><b>plenty of</b> + pluriel ou indénombrable = largement assez de, plein de (positif) : <i lang="en">plenty of time, plenty of apps</i>.</li><li><b>hardly any</b> + pluriel ou indénombrable = presque pas de : <i lang="en">hardly any sleep, hardly any buses</i>. De même <b>hardly anyone</b> (presque personne) et <b>hardly ever</b> (presque jamais).</li><li><b>a lot of / lots of</b> = beaucoup de, partout ; <b>much / many</b> surtout dans les questions et les négations : <i lang="en">I don’t have much time. How many apps do you use?</i></li><li><b>too much / too many</b> = trop de ; <b>far too much / far too many</b> = beaucoup trop de.</li></ul></div>
<div class="idea"><p><i lang="en">hardly</i> porte déjà le sens négatif : le verbe reste à la forme affirmative. <i lang="en">I get hardly any exercise</i> = <i lang="en">I get almost no exercise</i>.</p></div>
<div class="ex"><p><i lang="en">Don’t rush: we’ve got plenty of time.</i><br><i lang="en">There were hardly any people at the gym this morning.</i><br><i lang="en">You eat far too much sugar.</i></p></div>
<div class="warn"><p>Pièges des francophones : pas de double négation : <i lang="en">I <s>don’t</s> get hardly any sleep</i>. <b>hardly</b> ≠ <b>hard</b> : <i lang="en">I work hard</i> (je travaille dur) / <i lang="en">I hardly work</i> (je ne travaille presque pas). Et « la plupart des gens » = <i lang="en">most people</i>, pas <i lang="en"><s>most of people</s></i> : <i lang="en">most of</i> ne s’emploie que devant <i lang="en">the, my, these…</i> (<i lang="en">most of my friends</i>).</p></div>`,
  audio:'I get hardly any exercise. There are plenty of short workouts online. Don’t rush: we’ve got plenty of time. You eat far too much sugar.'},

 {kind:'Méthode', h:'Choosing the right quantifier',
  p:`<p><b>Quand :</b> devant chaque nom qui exprime une quantité (temps, argent, gens, minutes, conseils…). <b>Pourquoi :</b> en anglais, le choix dépend de la grammaire du nom (dénombrable ou non) <b>et</b> du message (positif ou négatif) ; le français « peu de / un peu de » ne suffit pas pour choisir. <b>Comment :</b></p>
<ol><li>Le nom est-il <b>dénombrable</b> (on peut dire <i lang="en">three apps</i>) ou <b>indénombrable</b> (<i lang="en">time, advice, sleep, information, money</i>) ?</li><li>Le message est-il <b>positif</b> (assez, ça va) ou <b>négatif</b> (pas assez) ? Beaucoup ou peu ?</li><li>Choisis : dénombrable → <i lang="en">a few / few / many</i> ; indénombrable → <i lang="en">a little / little / much</i> ; avec les deux → <i lang="en">a lot of, plenty of, hardly any</i>.</li></ol>`,
  demo:{enonce:'Complète : <i lang="en">We’ve got ___ time before the train, so let’s have a coffee.</i> puis <i lang="en">I know ___ people in this club, so I feel a bit lonely.</i>',
   etapes:[{f:'<i lang="en">time</i> est indénombrable (on ne dit pas <i lang="en">three times</i> dans ce sens).',w:'Donc ni <i lang="en">few</i> ni <i lang="en">many</i>.'},
    {f:'Le message est positif (on a le temps de prendre un café) → <i lang="en">a little time</i>, ou <i lang="en">plenty of time</i> si c’est largement assez.',w:'Avec <i lang="en">little</i> seul, on dirait qu’on n’a presque pas le temps : c’est le contraire du message.'},
    {f:'<i lang="en">people</i> est un pluriel dénombrable, et le message est négatif (<i lang="en">I feel lonely</i>) → <i lang="en">I know <b>few</b> people</i>, ou <i lang="en">very few</i>, ou <i lang="en">hardly any</i>.',w:'<i lang="en">a few</i> serait positif : « je connais quelques personnes, ça va ».'}],
   conclusion:'<i lang="en">We’ve got a little time (plenty of time) before the train, so let’s have a coffee. I know very few people (hardly any people) in this club, so I feel a bit lonely.</i>'}},

 {kind:'Pratique', h:'Practice: a few or a little?',
  p:`<p>Complete the sentence with <i lang="en">a few</i> or <i lang="en">a little</i>.</p><p><b>Question:</b> <i lang="en">Could you give me ___ advice about running shoes?</i></p>`, lab:'Two words', txt:['a little'],
  why:'<i lang="en">advice</i> est <b>indénombrable</b> en anglais (pas de <i lang="en">an advice</i> ni <i lang="en">advices</i>) : <i lang="en">a little advice</i>. Pour compter : <i lang="en">a piece of advice</i>.'},

 {kind:'Pratique', h:'Practice: hardly any',
  p:`<p>Rewrite the sentence with <i lang="en">hardly any</i>. Keep the same meaning.</p><p><b>Question:</b> <i lang="en">There are almost no buses after midnight.</i></p>`, lab:'Your sentence',
  txt:['There are hardly any buses after midnight.','After midnight, there are hardly any buses.'],
  why:'<i lang="en">There are hardly any buses after midnight.</i> <i lang="en">hardly any</i> remplace <i lang="en">almost no</i>, et le verbe reste affirmatif.'},

 {kind:'Pratique', h:'Practice: spot the mistake',
  p:`<p>Three sentences are correct and one has a mistake.</p><p><b>Question:</b> which sentence is <b>wrong</b>?</p>`,
  opts:['There’s plenty of fruit in the fridge.','We’ve got hardly any milk left.','Most of people don’t get enough sleep.','I’ve got a few questions for the coach.'], ans:2,
  why:'« la plupart des gens » = <i lang="en">most people</i>. <i lang="en">most of</i> n’est possible que devant un déterminant : <i lang="en">most of the people I know</i>, <i lang="en">most of my friends</i>.'},

 {kind:'Grammaire', h:'Advice and warnings: should, ought to, had better',
  p:`<p>Ben dit <i lang="en">I really <b>ought to</b> do something</i>, et Nadia l’avertit : <i lang="en">You<b>’d better</b> put your phone in another room, or you’ll never sleep properly.</i> Tu connais déjà <i lang="en">should</i> pour conseiller. Voici deux autres formes, chacune avec sa nuance.</p>
<div class="def"><ul><li><b>ought to + base verbale</b> = devrait, comme <i lang="en">should</i>, un peu plus insistant ou plus soutenu : <i lang="en">You ought to see a doctor.</i> À la négation, on utilise surtout <i lang="en">shouldn’t</i> (<i lang="en">ought not to</i> existe mais est rare).</li><li><b>had better (’d better) + base verbale</b> = ferais mieux de : un conseil <b>urgent</b> pour une situation <b>précise</b>, avec une menace sous-entendue (sinon…). <i lang="en">You’d better warm up, or you’ll get injured.</i> Négation : <b>had better not</b> : <i lang="en">You’d better not be late.</i></li></ul></div>
<div class="idea"><p>Malgré <i lang="en">had</i>, <i lang="en">had better</i> parle du <b>présent ou de l’avenir</b>, jamais du passé. Il sonne fort, presque comme un avertissement : avec un supérieur ou un client, préfère <i lang="en">should</i> ou <i lang="en">It might be a good idea to…</i>. Pour une vérité générale, c’est <i lang="en">should</i> : <i lang="en">People should drink enough water</i> (pas <i lang="en">had better</i>).</p></div>
<div class="ex"><p><i lang="en">It’s going to rain. We’d better take an umbrella.</i><br><i lang="en">You ought to cut down on coffee.</i><br><i lang="en">You’d better not eat that pizza: it’s been in the fridge for a week.</i></p></div>
<div class="warn"><p>Pièges : jamais de <i lang="en">to</i> après <i lang="en">had better</i> ni après <i lang="en">should</i> (<i lang="en"><s>You’d better to go</s></i>), mais toujours après <i lang="en">ought</i> (<i lang="en">ought <b>to</b> go</i>). La négation se place après <i lang="en">better</i> : <i lang="en">You’d better <b>not</b> go</i>, pas <i lang="en"><s>You hadn’t better go</s></i>. Et le verbe reste à la base : <i lang="en"><s>You’d better went</s></i>.</p></div>`,
  audio:'I really ought to do something. You’d better put your phone in another room at night. You’d better not be late. You ought to see a doctor.'},

 {kind:'Pratique', h:'Practice: a warning',
  p:`<p>Translate into English with <i lang="en">had better</i>.</p><p><b>Question:</b> «&nbsp;Tu ferais mieux de ne pas courir aujourd’hui, ton genou te fait encore mal.&nbsp;»</p>`, lab:'In English', long:true,
  txt:X(['You’d better not','You had better not'],['run today,','go running today,','go for a run today,'],['your knee still hurts.','your knee is still sore.','your knee is still painful.','because your knee still hurts.','because your knee is still sore.','because your knee is still painful.','as your knee still hurts.']),
  why:'<i lang="en">You’d better not run today: your knee still hurts.</i> <i lang="en">not</i> se place après <i lang="en">better</i>, et le verbe reste à la base (<i lang="en">run</i>). « me fait mal » = <i lang="en">hurts</i> ou <i lang="en">is sore</i>.'},

 {kind:'Pratique', h:'Practice: ought to',
  p:`<p>Rewrite the sentence with <i lang="en">ought to</i>. Keep the same meaning.</p><p><b>Question:</b> <i lang="en">You should drink more water during the day.</i></p>`, lab:'Your sentence', txt:['You ought to drink more water during the day.'],
  why:'<i lang="en">You ought to drink more water during the day.</i> Contrairement à <i lang="en">should</i>, <i lang="en">ought</i> est toujours suivi de <i lang="en">to</i>.'},

 {kind:'Grammaire', h:'Phrasal verbs: where does the object go?',
  p:`<p>Tu as appris les phrasal verbs de la santé : <i lang="en">take up, give up, cut down on, warm up</i>… Mais où placer le complément ? <i lang="en">I gave up it</i> ou <i lang="en">I gave it up</i> ? Cela dépend du type de verbe, et c’est une erreur que les anglophones remarquent tout de suite.</p>
<div class="def"><ul><li><b>Sans complément</b> (intransitifs) : <i lang="en">work out, warm up, cool down</i> : <i lang="en">I work out every morning.</i></li><li><b>Séparables</b> (verbe + particule) : <i lang="en">take up, give up, cut out, burn off</i>. Avec un nom, deux places possibles : <i lang="en">I gave up sugar</i> = <i lang="en">I gave sugar up</i>. Avec un <b>pronom</b>, il va <b>obligatoirement au milieu</b> : <i lang="en">I gave <b>it</b> up</i>.</li><li><b>Inséparables</b> (verbe + préposition, et tous les verbes à trois mots) : <i lang="en">get over, cut down on, keep up with, sign up for</i>. Le complément va toujours à la fin : <i lang="en">I got over <b>it</b></i>, <i lang="en">I cut down on <b>it</b></i>.</li></ul></div>
<div class="idea"><p>Astuce : un phrasal verb de trois mots est toujours inséparable. Pour les autres, le dictionnaire l’indique : <i lang="en">give sth up</i> (séparable : le complément peut aller au milieu), <i lang="en">get over sth</i> (inséparable).</p></div>
<div class="ex"><p><i lang="en">Yoga? I took it up last year.</i><br><i lang="en">The flu was bad, but I got over it in a week.</i><br><i lang="en">Salt is bad for you: try to cut it out.</i></p></div>
<div class="warn"><p>Le piège n° 1 : <i lang="en"><s>I gave up it</s></i>, <i lang="en"><s>She took up it</s></i>. Et <i lang="en">give up</i> suivi d’un verbe prend <b>-ing</b> : <i lang="en">He gave up <b>smoking</b></i>, jamais <i lang="en"><s>gave up to smoke</s></i>.</p></div>`},

 {kind:'Pratique', h:'Practice: use a pronoun',
  p:`<p>Answer the question. Replace <i lang="en">tennis</i> with <i lang="en">it</i>.</p><p><b>Question:</b> <i lang="en">When did you take up tennis?</i> («&nbsp;Je m’y suis mis l’année dernière.&nbsp;»)</p>`, lab:'Your answer', txt:['I took it up last year.'],
  why:'<i lang="en">take up</i> est séparable : le pronom se place au milieu. <i lang="en">I took it up last year</i>, jamais <i lang="en"><s>I took up it</s></i>.'},

 {kind:'Prononciation', h:'The hidden ’d in you’d better',
  p:`<p>Dans <i lang="en">you’d better</i>, le <i lang="en">’d</i> (= <i lang="en">had</i>) s’entend à peine : le <i lang="en">d</i> se colle au <i lang="en">b</i> de <i lang="en">better</i>. Beaucoup d’anglophones l’avalent presque à l’oral, mais il reste à l’écrit (<i lang="en">You better go</i> est très familier, surtout américain).</p>
<div class="def"><p><i lang="en">you’d better</i> : « youd-<b>bè</b>-teu » · <i lang="en">we’d better</i> : « wid-<b>bè</b>-teu » · <i lang="en">ought to</i> /ˈɔːtə/ : « <b>ôô</b>-teu », le <i lang="en">gh</i> est muet. L’accent tombe sur <i lang="en">better</i> et sur <i lang="en">ought</i>.</p></div>
<div class="warn"><p>Les francophones prononcent parfois le <i lang="en">gh</i> de <i lang="en">ought</i>, ou disent « ou-te » : en anglais britannique, <i lang="en">ought</i> rime avec <i lang="en">sport</i> et <i lang="en">short</i>.</p></div>
<p>Listen, then repeat the sentence.</p>`,
  dire:'You’d better warm up before you start running. You ought to stretch afterwards.'},

 {kind:'Lecture', h:'Small changes, big results',
  p:`<p>Read this article from a health magazine. You can also listen to it.</p>
<div class="blk" data-t="Small changes, big results"><p lang="en">Most of us know what we ought to do: eat more vegetables, move more, sleep better. The problem is doing it. According to many coaches, the answer is not a dramatic new start, but a few small changes that are easy to keep up.</p><p lang="en">Take exercise. Plenty of people sign up for a gym in January and give up by March. Instead, try adding a little movement to your normal day: get off the bus one stop early, take the stairs, or do a ten-minute workout while the pasta is cooking.</p><p lang="en">Food works the same way. Very few people manage to cut out sugar completely, and those who try often end up eating more. It’s far easier to cut down on it gradually: one sugar in your tea instead of two, fruit instead of a biscuit.</p><p lang="en">Finally, sleep. Hardly any of us get the eight hours we need, often because of screens. If you want to sleep better, you’d better leave your phone outside the bedroom. Buy an old-fashioned alarm clock: it costs very little, and it might change your life.</p></div>
<p><b>Question:</b> according to the article, what is the best way to change your lifestyle?</p>`,
  audio:'Most of us know what we ought to do: eat more vegetables, move more, sleep better. The problem is doing it. According to many coaches, the answer is not a dramatic new start, but a few small changes that are easy to keep up. Take exercise. Plenty of people sign up for a gym in January and give up by March. Instead, try adding a little movement to your normal day: get off the bus one stop early, take the stairs, or do a ten-minute workout while the pasta is cooking. Food works the same way. Very few people manage to cut out sugar completely, and those who try often end up eating more. It’s far easier to cut down on it gradually: one sugar in your tea instead of two, fruit instead of a biscuit. Finally, sleep. Hardly any of us get the eight hours we need, often because of screens. If you want to sleep better, you’d better leave your phone outside the bedroom. Buy an old-fashioned alarm clock: it costs very little, and it might change your life.',
  opts:['Make a dramatic new start in January.','Cut out sugar completely.','Join a gym and go every day.','Make a few small changes that you can keep up.'], ans:3,
  why:'<i lang="en">The answer is not a dramatic new start, but a few small changes that are easy to keep up.</i> L’article dit même que <b>très peu</b> de gens (<i lang="en">very few people</i>) arrivent à supprimer complètement le sucre.'},

 {kind:'Dictée', h:'Dictation: no time to exercise?',
  p:'Listen and write the sentence exactly. Be careful with the quantifiers.',
  dictee:'There are plenty of ways to stay fit, even if you have very little time.',
  why:'<i lang="en">plenty of ways</i> (pluriel, positif) et <i lang="en">very little time</i> (indénombrable, négatif).'},

 {kind:'Oral', h:'Repeat from memory: a resolution',
  p:'The sentence is not written. Listen, then say it from memory. Remember: the <i lang="en">gh</i> in <i lang="en">ought</i> is silent.',
  dire:{t:'I really ought to cut down on coffee and get more sleep.', cache:true}},

 {kind:'Oral', h:'Give your friend some advice',
  p:`<p>Speak for about one minute. Your friend sleeps five hours a night, eats a lot of junk food and never exercises, but says he has no time to change. Give him advice: some gentle, some more urgent. Use quantifiers, <i lang="en">ought to</i>, <i lang="en">had better</i> and at least two phrasal verbs.</p>`,
  oral:{modele:'OK, listen. You don’t need to change everything at once. First, you’d better get more sleep, or you’ll get ill. Five hours is far too little. Put your phone in the kitchen at night. Then food: you ought to cut down on takeaways. You don’t have to cut them out completely, but cook a few simple meals at the weekend. And exercise: you say you’ve got hardly any time, but a twenty-minute walk is enough to start. Maybe take up swimming, it’s great for your back. Just warm up properly and don’t give up after a week!',
   criteres:['I gave gentle advice with should or ought to','I gave an urgent warning with had better (’d better)','I used at least two quantifiers (a few, a little, plenty of, hardly any, far too…)','I used at least two phrasal verbs (cut down on, take up, warm up, give up…)','I pronounced ought without the gh']}},

 {kind:'Écriture', h:'Reply on a health forum',
  p:'On a health forum, Lucas writes: «&nbsp;I’m 35, I work in an office and I feel tired all the time. I hardly ever exercise and I eat a lot of takeaways. Where should I start?&nbsp;» Write a reply of about 120 words. Give advice about sleep, exercise and food, use quantifiers, <i lang="en">ought to</i> or <i lang="en">had better</i>, and some phrasal verbs.',
  ecrire:{min:110, modele:'Hi Lucas, I was in the same situation a few years ago, so here’s my advice. First, you ought to look at your sleep. Most people need seven or eight hours, and if you’re on your phone until midnight, you’ll get hardly any real rest. You’d better leave it in the kitchen at night. Next, don’t try to change everything at once. Take up something easy, like walking to work or swimming twice a week. If you do a little exercise every day, you’ll soon feel the difference. As for food, you don’t have to cut out takeaways completely. Just cut down on them and cook a few simple meals at the weekend. Good luck, and let us know how it goes! Maria',
   criteres:[{t:'I used a quantifier (a few, a little, plenty of, hardly any…)', re:'\\b(a few|a little|few|little|plenty of|hardly any|hardly anyone)\\b'},{t:'I gave advice with ought to, had better or should', re:"\\b(ought to|had better|should)\\b|[’']d better"},{t:'I used at least one phrasal verb (take up, cut down on, give up…)', re:'\\b(take|took|taking|give|gave|giving|cut|cutting|warm|warming|work|working|sign|signing|get|getting|keep|keeping)\\s+(\\w+\\s+)?(up|down|out|over)\\b'},'I gave advice about sleep, exercise and food','I avoided « most of people » and double negatives with hardly']}},

 {kind:'Récapitulatif', h:'Ce qu’il faut retenir',
  p:`<div class="keep"><ul><li>Dénombrable pluriel : <b>a few</b> (quelques, positif) / <b>few</b> (peu de, négatif). Indénombrable : <b>a little</b> (un peu de) / <b>little</b> (peu de). <i lang="en">advice, time, information, money</i> sont indénombrables.</li><li><b>plenty of</b> = largement assez de ; <b>hardly any</b> = presque pas de, avec un verbe affirmatif (pas de double négation). <i lang="en">hardly anyone, hardly ever</i>. <b>far too much / far too many</b> = beaucoup trop.</li><li><i lang="en">most people</i>, pas <i lang="en"><s>most of people</s></i>. <i lang="en">much / many</i> surtout en question et négation.</li><li>Conseil : <b>should</b>, <b>ought to</b> + base (plus insistant). Avertissement urgent et précis : <b>had better (’d better) + base</b>, négation <b>had better not</b>. Jamais <i lang="en">to</i> après <i lang="en">had better</i>.</li><li>Phrasal verbs : <i lang="en">work out, warm up, cool down, take up, give up, cut down on, cut out, get over, keep up with, sign up for, burn off</i>. Séparables + pronom : <i lang="en">I gave it up</i>. Inséparables : <i lang="en">I got over it</i>. <i lang="en">give up + -ing</i>.</li><li>Collocations : <i lang="en">a balanced diet, get enough sleep, do exercise, keep fit, skip breakfast</i>. Pas de <i lang="en">make sport</i>.</li></ul></div>`},

 {kind:'Mission', h:'At the sports centre',
  p:'A friend of yours wants to join a sports centre but doesn’t speak much English. You listen to the conversation at the reception desk to help her. Listen, then answer the questions one by one. You can listen again at any time.',
  audio:[['Receptionist','Hi there. How can I help?'],['Visitor','Hi. I’d like to sign up for some classes, but I’ve never really done any sport, so I’m a bit nervous.'],['Receptionist','No problem. We’ve got plenty of classes for beginners. What are you interested in?'],['Visitor','Maybe yoga, or swimming. I’ve got a bad back, so I can’t do anything too hard.'],['Receptionist','Then you’d better avoid the spinning classes. Swimming is great for your back. There are a few places left in the Tuesday evening group.'],['Visitor','And yoga?'],['Receptionist','I’m afraid there are hardly any places left this term. There’s one on Friday mornings, at seven.'],['Visitor','Seven in the morning? I don’t think so. I’ll take the swimming.'],['Receptionist','Good choice. The first session is free, and after that it’s six pounds a session, or forty-five pounds for ten. Oh, and you ought to bring a padlock for the lockers.'],['Visitor','Great, thanks.']], cache:true,
  parts:[
   {q:'a) Why does the visitor want gentle exercise?', opts:['Because of a bad back','Because of a knee injury','Because she has very little time','Because the other classes are full'], ans:0, hint:'Listen to what the visitor says just after mentioning yoga and swimming.', why:'<i lang="en">I’ve got a bad back, so I can’t do anything too hard.</i>'},
   {q:'b) Which class does the visitor choose, and when is it?', opts:['Yoga on Friday mornings','Spinning on Tuesday evenings','Swimming on Tuesday evenings','Swimming on Friday mornings'], ans:2, hint:'The yoga class is at seven in the morning, and she doesn’t like that.', why:'Elle choisit la natation (<i lang="en">I’ll take the swimming</i>) ; il reste quelques places le mardi soir (<i lang="en">a few places left in the Tuesday evening group</i>).'},
   {q:'c) How much do ten sessions cost if you buy them together? Write the price in pounds.', lab:'Price', txt:['£45','45 pounds','forty-five pounds'], hint:'The receptionist gives two prices: one for a single session and one for ten.', why:'<i lang="en">forty-five pounds for ten</i> : 45 £, au lieu de 10 × 6 = 60 £ à la séance.'},
   {q:'d) Complete the receptionist’s words about the yoga class: <i lang="en">I’m afraid there are ___ places left this term.</i>', lab:'Two words', txt:['hardly any'], hint:'It means “almost no”.', why:'<i lang="en">hardly any places</i> = presque plus de places. Le verbe (<i lang="en">are</i>) reste affirmatif.'},
   {q:'e) Translate the receptionist’s advice with <i lang="en">had better</i>: «&nbsp;Tu ferais mieux d’apporter un cadenas pour les casiers.&nbsp;»', lab:'In English', long:true, txt:X(['You’d better','You had better'],'bring a padlock for the',['lockers.','locker.']), hint:'had better + base form, with no “to”.', why:'<i lang="en">You’d better bring a padlock for the lockers.</i> Pas de <i lang="en">to</i> après <i lang="en">had better</i>. La réceptionniste, elle, a dit <i lang="en">you ought to</i>, un conseil un peu moins pressant.'}],
  sol:'<p lang="en">Visitor: I’d like to sign up for some classes… I’ve got a bad back. – Receptionist: Then you’d better avoid the spinning classes… There are a few places left in the Tuesday evening group… I’m afraid there are hardly any places left [in yoga]… six pounds a session, or forty-five pounds for ten.</p><p>Elle choisit la natation le mardi soir, à cause de son dos. Dix séances coûtent 45 £ (au lieu de 60 £). <i lang="en">hardly any</i> = presque pas de ; <i lang="en">You’d better bring a padlock</i>, sans <i lang="en">to</i>.</p>'},

 {kind:'Mission', h:'A health plan for a friend',
  p:`<p>Your friend Emma sends you this message. Read it, then answer the questions and help her make a plan.</p>
<div class="blk" data-t="Message from Emma"><p lang="en">Hi! I need your help. The doctor says my blood pressure is a bit high and I need to change my lifestyle, but I don’t know where to start. Here’s my typical week: I drink about six coffees a day, I hardly ever cook (I live on sandwiches and takeaways), and I sleep about five hours a night because I watch series until 1 a.m. I used to play basketball at university, but I stopped when I started working. I’ve got very little free time during the week, but my weekends are pretty free. Oh, and I’ve got a big presentation on Monday, so I’m really stressed at the moment. Any ideas? Emma</p></div>`,
  parts:[
   {q:'a) How much free time does Emma have during the week?', opts:['Plenty of free time','A lot of free time','Very little free time','No free time at all'], ans:2, hint:'Find the sentence about her free time.', why:'<i lang="en">I’ve got very little free time during the week</i> : très peu, mais pas « pas du tout ». Le week-end, elle est plutôt libre.'},
   {q:'b) Give Emma advice about coffee. Use <i lang="en">ought to</i> and <i lang="en">cut down on</i>.', lab:'Your advice', long:true, txt:X('You ought to cut down on',['coffee.','caffeine.','your coffee.','coffee a bit.','drinking coffee.','the coffee.']), hint:'You ought to + base form; cut down on + noun.', why:'<i lang="en">You ought to cut down on coffee.</i> <i lang="en">ought</i> est suivi de <i lang="en">to</i>, et <i lang="en">cut down on</i> est inséparable : le complément va à la fin.'},
   {q:'c) Emma used to play basketball. Tell her to start again, using <i lang="en">take up</i>, <i lang="en">it</i> and <i lang="en">again</i>.', lab:'Your advice', long:true, txt:X(['You should','You ought to','Why don’t you','Maybe you should','You could'],['take it up again.','take it up again at the weekend.','take it up again at weekends.']), hint:'take up is separable: where does the pronoun go?', why:'<i lang="en">You should take it up again.</i> Avec un pronom, il se place au milieu du phrasal verb séparable : <i lang="en">take it up</i>, jamais <i lang="en">take up it</i>.'},
   {q:'d) Why is Emma stressed at the moment?', opts:['Because of her blood pressure test','Because she can’t play basketball','Because she has too much free time','Because of a big presentation on Monday'], ans:3, hint:'Look at the end of the message.', why:'<i lang="en">I’ve got a big presentation on Monday, so I’m really stressed at the moment.</i>'},
   {q:'e) Warn Emma about her series with <i lang="en">had better not</i>: «&nbsp;Tu ferais mieux de ne pas regarder de séries après 23 heures.&nbsp;»', lab:'Your warning', long:true, txt:X(['You’d better not','You had better not'],['watch series','watch any series','watch TV series','watch any TV series','watch anything'],['after 11 p.m.','after 11 pm','after 11pm','after eleven','after 11','after eleven o’clock','after 11 o’clock','after eleven p.m.','after eleven at night','after 23:00']), hint:'had better not + base form, with no “to”.', why:'<i lang="en">You’d better not watch series after 11 p.m.</i> La négation se place après <i lang="en">better</i>, et le verbe reste à la base.'}],
  sol:'<p>Emma a très peu de temps libre en semaine (<i lang="en">very little free time</i>), mais ses week-ends sont libres : c’est là qu’elle peut reprendre le basket (<i lang="en">You should take it up again at the weekend</i>). Conseils : <i lang="en">You ought to cut down on coffee.</i> Avertissement : <i lang="en">You’d better not watch series after 11 p.m.</i> Elle est stressée à cause de sa présentation de lundi.</p>'},
]},
);
})();
